                    </circle>
                    <text x="400" y="105" text-anchor="middle" fill="white">Fe³⁺</text>

                    <circle cx="450" cy="150" r="15" fill="#0ff" id="caAtom">
                        <animate attributeName="cy" values="150;100;150" dur="2.5s" repeatCount="indefinite"/>
                    </circle>
                    <text x="450" y="155" text-anchor="middle" fill="white">Ca²⁺</text>

                    <circle cx="500" cy="200" r="15" fill="#ff0" id="znAtom">
                        <animate attributeName="cy" values="200;150;200" dur="2s" repeatCount="indefinite"/>
                    </circle>
                    <text x="500" y="205" text-anchor="middle" fill="white">Zn²⁺</text>
                </g>

                <!-- LÍNEAS DE INTERACCIÓN -->
                <line id="lineFe" x1="140" y1="150" x2="385" y2="100" stroke="#f0f" stroke-width="2" stroke-dasharray="5,5">
                    <animate attributeName="stroke-dashoffset" values="0;20" dur="1s" repeatCount="indefinite"/>
                </line>
                <line id="lineCa" x1="140" y1="150" x2="435" y2="150" stroke="#0ff" stroke-width="2" stroke-dasharray="5,5">
                    <animate attributeName="stroke-dashoffset" values="10;0" dur="1s" repeatCount="indefinite"/>
                </line>
                <line id="lineZn" x1="140" y1="150" x2="485" y2="200" stroke="#ff0" stroke-width="2" stroke-dasharray="5,5">
                    <animate attributeName="stroke-dashoffset" values="0;15" dur="1s" repeatCount="indefinite"/>
                </line>

                <!-- ZONA DE QUELACIÓN -->
                <rect x="250" y="120" width="100" height="60" fill="#f00" opacity="0.3" rx="10">
                    <animate attributeName="opacity" values="0.3;0.7;0.3" dur="2s" repeatCount="indefinite"/>
                </rect>
                <text x="300" y="155" text-anchor="middle" fill="white" font-weight="bold">QUELACIÓN</text>
            </svg>
        </div>
    </div>

    <!-- SECCIÓN 4: CONTROLES BIOTECNOLÓGICOS -->
    <div class="cyber-section">
        <h2><span class="section-number">[04]</span> PROTOCOLOS DE CONTROL</h2>

        <div class="protocol-grid">
            <div class="protocol-card" data-effect="high">
                <div class="protocol-icon">🔥</div>
                <h3>TERMOLISIS</h3>
                <div class="protocol-stats">
                    <span class="stat">LECTINAS: -99%</span>
                    <span class="stat">TANINOS: -70%</span>
                </div>
                <div class="protocol-desc">
