<!-- SCRIPT PRINCIPAL -->
<script>
// ============================================
// SISTEMA DE SIMULACIÓN AVANZADO
// ============================================

class AntiNutrientSimulator {
    constructor() {
        this.state = {
            pH: 7.0,
            vitC: 0,
            ferment: 0,
            soak: 0,
            heat: false,
            protocol: \'none\'
        };
        this.init();
    }

    init() {
        // Configurar listeners
        document.getElementById(\'simPH\').addEventListener(\'input\', (e) => {
            this.state.pH = parseFloat(e.target.value);
            document.getElementById(\'phValue\').textContent = this.state.pH.toFixed(1);
            this.update();
        });

        document.getElementById(\'simVitC\').addEventListener(\'input\', (e) => {
            this.state.vitC = parseInt(e.target.value);
            document.getElementById(\'vitcValue\').textContent = `${this.state.vitC} mg`;
            this.update();
        });

        document.getElementById(\'simFerment\').addEventListener(\'input\', (e) => {
            this.state.ferment = parseInt(e.target.value);
            document.getElementById(\'fermentValue\').textContent = `${this.state.ferment}h`;
            this.update();
        });

        document.getElementById(\'simSoak\').addEventListener(\'input\', (e) => {
            this.state.soak = parseInt(e.target.value);
            document.getElementById(\'soakValue\').textContent = `${this.state.soak}h`;
            this.update();
        });

        this.update();
    }

    calculateFitatos() {
        let fitatos = 100;
        
        // Efecto del pH
        fitatos -= Math.abs(7 - this.state.pH) * 10;
        
        // Efecto de la fermentación
        fitatos -= this.state.ferment * 1.2;
        
        // Efecto del remojo
        fitatos -= this.state.soak * 2;
        
        // Efecto del protocolo
        if (this.state.protocol === \'ferment\') fitatos -= 80;
        if (this.state.protocol === \'germ\') fitatos -= 40;
        if (this.state.protocol === \'heat\') fitatos -= 20;
        if (this.state.protocol === \'soak\') fitatos -= 30;
        
        return Math.max(5, Math.min(100, fitatos));
    }

    calculateBioavailability() {
        const fitatos = this.calculateFitatos();
        let bio = 100 - fitatos * 0.7;
        
        // Mejora por vitamina C
        bio += this.state.vitC * 0.15;
        
        // Mejora por pH óptimo
        if (this.state.pH > 6.5 && this.state.pH < 7.5) bio += 15;
        
        return Math.max(10, Math.min(95, bio));
    }

    calculateMineralAbsorption() {
        const base = this.calculateBioavailability();
        
        return {
            fe: Math.max(5, base - 15 + (this.state.vitC * 0.25)),
            ca: Math.max(10, base - 10),
            zn: Math.max(8, base - 12)
        };
    }

    update() {
        const fitatos = this.calculateFitatos();
        const bio = this.calculateBioavailability();
        const minerals = this.calculateMineralAbsorption();
        
        // Actualizar estadísticas
        document.getElementById(\'statFitatos\').textContent = `${fitatos.toFixed(0)}%`;
        document.getElementById(\'statBio\').textContent = bio < 40 ? \'BAJA\' : bio < 70 ? \'MEDIA\' : \'ALTA\';
        document.getElementById(\'absorptionIndex\').textContent = `${bio.toFixed(0)}%`;
        document.getElementById(\'finalBio\').textContent = `${bio.toFixed(0)}%`;
        
        // Barras de estadísticas
        document.getElementById(\'fitatoBar\').style.width = `${fitatos}%`;
        document.getElementById(\'bioBar\').style.width = `${bio}%`;
        document.getElementById(\'redoxBar\').style.width = `${Math.min(100, this.state.vitC * 0.5)}%`;
        document.getElementById(\'statRedox\').textContent = `${Math.min(100, this.state.vitC * 0.5).toFixed(0)}%`;
        
        // Minerales
        document.getElementById(\'feValue\').textContent = `${minerals.fe.toFixed(0)}%`;
        document.getElementById(\'caValue\').textContent = `${minerals.ca.toFixed(0)}%`;
        document.getElementById(\'znValue\').textContent = `${minerals.zn.toFixed(0)}%`;
        
        document.getElementById(\'feBar\').style.width = `${minerals.fe}%`;
        document.getElementById(\'caBar\').style.width = `${minerals.ca}%`;
        document.getElementById(\'znBar\').style.width = `${minerals.zn}%`;
        
        // Log del simulador
        const log = document.getElementById(\'simLog\');
        log.innerHTML = `
            > pH: ${this.state.pH.toFixed(1)} | Vit C: ${this.state.vitC}mg
            > Fermentación: ${this.state.ferment}h | Remojo: ${this.state.soak}h
            > Fitato activo: ${fitatos.toFixed(0)}%
            > Biodisponibilidad: ${bio.toFixed(0)}%
            > Protocolo activo: ${this.state.protocol.toUpperCase()}
        `;
        
        // Actualizar animación molecular
        this.updateAnimation(fitatos);
    }

    updateAnimation(fitatos) {
        const opacity = fitatos / 100;
        const lineFe = document.getElementById(\'lineFe\');
        const lineCa = document.getElementById(\'lineCa\');
        const lineZn = document.getElementById(\'lineZn\');

        if (lineFe) lineFe.style.opacity = fitatos > 70 ? opacity : 0.3;
        if (lineCa) lineCa.style.opacity = fitatos > 70 ? opacity : 0.3;
        if (lineZn) lineZn.style.opacity = fitatos > 70 ? opacity : 0.3;
    }

    applyProtocol(protocol) {
        this.state.protocol = protocol;
        this.update();

        const buttons = document.querySelectorAll(\'.protocol-btn\');
        buttons.forEach(btn => {
            const btnProtocol = btn.getAttribute(\'data-protocol\');
            const isActive = String(btnProtocol).toLowerCase() === String(protocol).toLowerCase();
            btn.classList.toggle(\'active\', isActive);

            const card = btn.closest(\'.protocol-card\');
            if (card) card.classList.toggle(\'active\', isActive);
        });
    }
}

// ============================================
// SISTEMA DE QUIZ
// ============================================

class QuizSystem {
    constructor() {
        this.questions = [
            {
                question: "UNA PERSONA CON ANEMIA CONSUME LEGUMBRES GERMINADAS. ¿QUÉ OCURRE BIOQUÍMICAMENTE?",
                options: [
                    "LOS FITATOS SE DEGRADAN POR FITASA ENDÓGENA",
                    "LOS MINERALES SE OXIDAN RÁPIDAMENTE",
                    "NO HAY CAMBIO SIGNIFICATIVO"
                ],
                correct: 0,
                explanation: ">> CORRECTO: LA GERMINACIÓN ACTIVA FITASAS INTRÍNSECAS QUE HIDROLIZAN FITATOS."
            },
            {
                question: "¿POR QUÉ LA VITAMINA C MEJORA LA ABSORCIÓN DE HIERRO NO-HEMO?",
                options: [
                    "REDUCE Fe³⁺ A Fe²⁺, MÁS SOLUBLE",
                    "AUMENTA EL pH INTESTINAL",
                    "QUELA EL OXALATO COMPETITIVO"
                ],
                correct: 0,
                explanation: ">> CORRECTO: EL ÁCIDO ASCÓRBICO ES UN AGENTE REDUCTOR QUE MANTIENE EL HIERRO EN ESTADO FERROSO."
            },
            {
                question: "EN EL PROCESO HABER-BOSCH DE FERTILIZANTES, ¿QUÉ RELACIÓN TIENE CON LOS ANTINUTRIENTES?",
                options: [
                    "NINGUNA, SON PROCESOS DIFERENTES",
                    "LOS FERTILIZANTES NITROGENADOS REDUCEN FITATOS",
                    "LA FIJACIÓN DE N₂ MEJORA CONTENIDO PROTEICO"
                ],
                correct: 2,
                explanation: ">> CORRECTO: MAYOR NITRÓGENO DISPONIBLE = MAYOR SÍNTESIS PROTEICA = MAYOR CONTENIDO NUTRICIONAL."
            }
        ];
        
        this.currentQuestion = 0;
        this.score = 0;
        this.init();
    }

    init() {
        this.renderQuestion();
    }

    renderQuestion() {
        const quizContent = document.getElementById(\'quizContent\');
        const q = this.questions[this.currentQuestion];
        
        quizContent.innerHTML = `
            <div class="quiz-question">${q.question}</div>
            <div class="quiz-options">
                ${q.options.map((option, index) => `
                    <button type="button" class="quiz-option" onclick="quizSystem.answer(${index})">
                        ${option}
                    </button>
                `).join(\'\')}
            </div>
        `;
        
        document.getElementById(\'quizScore\').textContent = `SCORE: ${this.score}/${this.questions.length}`;
    }

    answer(selected) {
        const q = this.questions[this.currentQuestion];
        const options = document.querySelectorAll(\'.quiz-option\');
        const log = document.getElementById(\'quizLog\');
        
        options.forEach((option, index) => {
            option.disabled = true;
            if (index === q.correct) {
                option.classList.add(\'correct\');
            } else if (index === selected) {
                option.classList.add(\'incorrect\');
            }
        });
        
        if (selected === q.correct) {
            this.score++;
            log.innerHTML = `>> RESPUESTA CORRECTA\\n${q.explanation}`;
        } else {
            log.innerHTML = `>> RESPUESTA INCORRECTA\\n${q.explanation}`;
        }
        
        setTimeout(() => {
            this.currentQuestion++;
            if (this.currentQuestion < this.questions.length) {
                this.renderQuestion();
                log.innerHTML += \'\\n>> SIGUIENTE PREGUNTA CARGADA\';
            } else {
                document.getElementById(\'quizContent\').innerHTML = `
                    <div class="quiz-complete">
                        <div class="complete-title">EVALUACIÓN COMPLETADA</div>
                        <div class="complete-score">PUNTAJE FINAL: ${this.score}/${this.questions.length}</div>
                        <div class="complete-message">
                            ${this.score === this.questions.length ? \'>> SISTEMA DOMINADO: COMPETENCIA AVANZADA\' : \'>> CONTINÚA ESTUDIANDO: REVISA LOS CONCEPTOS\'}
                        </div>
                    </div>
                `;
                log.innerHTML = \'>> SISTEMA DE EVALUACIÓN FINALIZADO\';
            }
        }, 2000);
    }
}

// ============================================
// INICIALIZACIÓN DEL SISTEMA
// ============================================

let simulator;
let quizSystem;

document.addEventListener(\'DOMContentLoaded\', () => {
    // Efecto de glitch en el título
    const glitchElements = document.querySelectorAll(\'.glitch\');
    glitchElements.forEach(el => {
        setInterval(() => {
            if (Math.random() > 0.7) {
                el.style.textShadow = \'2px 2px 0 #f0f, -2px -2px 0 #0ff\';
                setTimeout(() => {
                    el.style.textShadow = \'none\';
                }, 100);
            }
        }, 2000);
    });
    
    // Inicializar sistemas
    simulator = new AntiNutrientSimulator();
    quizSystem = new QuizSystem();
    window.quizSystem = quizSystem;
    
    // Exponer funciones globales
    window.applyProtocol = (protocol) => simulator.applyProtocol(protocol);

    // Error interactivo: expandir detalle de corrección
    const errorItems = document.querySelectorAll(\'.error-item\');
    errorItems.forEach(item => {
        item.addEventListener(\'click\', () => {
            const open = item.classList.toggle(\'active\');
            if (open) {
                item.scrollIntoView({ behavior: \'smooth\', block: \'center\' });
            }
        });
    });

    // SVG interactivo: animar nodos según protocolo y estado
    function updateSVGStatus() {
        const protocols = {
            heat: { color: \'#ffa020\', pulse: 1.1 },
            soak: { color: \'#52d8ff\', pulse: 1.03 },
            ferment: { color: \'#88ff4c\', pulse: 1.15 },
            germ: { color: \'#ff7cff\', pulse: 1.08 },
            none: { color: \'#66f6ff\', pulse: 1 }
        };
        const p = simulator?.state?.protocol || \'none\';
        const cfg = protocols[p] || protocols.none;

        document.querySelectorAll(\'#phytate circle, #minerals circle\').forEach(c => {
            c.style.stroke = cfg.color;
            c.style.filter = `drop-shadow(0 0 ${Math.min(12, 8 * cfg.pulse)}px ${cfg.color})`;
            c.setAttribute(\'transform\', `scale(${cfg.pulse})`);
        });
    }

