// ========== FUNCIONES DE UTILIDAD ==========
function formatScientific(value, decimals = 2) {
    if (value === 0) return \'0\';
    if (Math.abs(value) >= 1) {
        return value.toFixed(decimals);
    }
    
    const exponent = Math.floor(Math.log10(Math.abs(value)));
    const mantissa = value / Math.pow(10, exponent);
    
    return mantissa.toFixed(decimals) + \'×10\' + superscript(exponent);
}

function superscript(num) {
    const superscripts = [\'⁰\', \'¹\', \'²\', \'³\', \'⁴\', \'⁵\', \'⁶\', \'⁷\', \'⁸\', \'⁹\'];
    const sign = num < 0 ? \'⁻\' : \'\';
    const digits = Math.abs(num).toString().split(\'\');
    return sign + digits.map(d => superscripts[parseInt(d)]).join(\'\');
}

function wavelengthToColor(wavelength) {
    let r, g, b;
    if (wavelength >= 380 && wavelength < 440) {
        r = -(wavelength - 440) / (440 - 380);
        g = 0;
        b = 1;
    } else if (wavelength >= 440 && wavelength < 490) {
        r = 0;
        g = (wavelength - 440) / (490 - 440);
        b = 1;
    } else if (wavelength >= 490 && wavelength < 510) {
        r = 0;
        g = 1;
        b = -(wavelength - 510) / (510 - 490);
    } else if (wavelength >= 510 && wavelength < 580) {
        r = (wavelength - 510) / (580 - 510);
        g = 1;
        b = 0;
    } else if (wavelength >= 580 && wavelength < 645) {
        r = 1;
        g = -(wavelength - 645) / (645 - 580);
        b = 0;
    } else if (wavelength >= 645 && wavelength <= 780) {
        r = 1;
        g = 0;
        b = 0;
    } else {
        r = 0.5;
        g = 0.5;
        b = 0.5;
    }
    
    // Intensidad
    let intensity;
    if (wavelength >= 380 && wavelength < 420) {
        intensity = 0.3 + 0.7 * (wavelength - 380) / (420 - 380);
    } else if (wavelength >= 420 && wavelength < 700) {
        intensity = 1;
    } else if (wavelength >= 700 && wavelength <= 780) {
        intensity = 0.3 + 0.7 * (780 - wavelength) / (780 - 700);
    } else {
        intensity = 0.5;
    }
    
    r = Math.floor(255 * Math.pow(r * intensity, 0.8));
    g = Math.floor(255 * Math.pow(g * intensity, 0.8));
    b = Math.floor(255 * Math.pow(b * intensity, 0.8));
    
    return `rgb(${r}, ${g}, ${b})`;
}

// ========== SIMULADOR DE ORBITALES ==========
function updateOrbitalVisualization() {
    const orbitalType = document.getElementById(\'orbital-type\').value;
    const probability = parseInt(document.getElementById(\'probability-slider\').value);
    const showNodes = document.getElementById(\'show-nodes\').checked;
    const showPhase = document.getElementById(\'show-phase\').checked;
    const showGrid = document.getElementById(\'show-grid\').checked;
    
    const data = orbitalData[orbitalType];
    
    // Actualizar información
    document.getElementById(\'orbital-title\').textContent = `ORBITAL ${orbitalType.toUpperCase()}`;
    document.getElementById(\'quantum-numbers\').textContent = `n=${data.n}, l=${data.l}, m=${data.m}`;
    document.getElementById(\'node-count\').textContent = `Radiales: ${data.nodes.radial}, Angulares: ${data.nodes.angular}`;
    document.getElementById(\'orbital-energy\').textContent = `${data.energy} eV`;
    document.getElementById(\'wave-function\').textContent = data.waveFunc;
    document.getElementById(\'shape-desc\').textContent = data.shape;
    document.getElementById(\'prob-value\').textContent = `${probability}%`;
    
    // Actualizar visualización SVG
    const svg = document.getElementById(\'orbital-svg\');
    svg.innerHTML = \'\';
    
    const centerX = 200;
    const centerY = 150;
    const baseRadius = 80;
    const probRadius = baseRadius * (probability / 100);
    
    // Fondo
    const bg = document.createElementNS(\'http://www.w3.org/2000/svg\', \'rect\');
    bg.setAttribute(\'width\', \'400\');
    bg.setAttribute(\'height\', \'300\');
    bg.setAttribute(\'fill\', \'#000\');
    svg.appendChild(bg);
    
    // Rejilla si está activada
    if (showGrid) {
        for (let i = 0; i <= 400; i += 40) {
            const line = document.createElementNS(\'http://www.w3.org/2000/svg\', \'line\');
            line.setAttribute(\'x1\', i);
            line.setAttribute(\'y1\', \'0\');
            line.setAttribute(\'x2\', i);
            line.setAttribute(\'y2\', \'300\');
            line.setAttribute(\'stroke\', \'#333\');
            line.setAttribute(\'stroke-width\', \'0.5\');
            svg.appendChild(line);
        }
        for (let i = 0; i <= 300; i += 30) {
            const line = document.createElementNS(\'http://www.w3.org/2000/svg\', \'line\');
            line.setAttribute(\'x1\', \'0\');
            line.setAttribute(\'y1\', i);
            line.setAttribute(\'x2\', \'400\');
            line.setAttribute(\'y2\', i);
            line.setAttribute(\'stroke\', \'#333\');
            line.setAttribute(\'stroke-width\', \'0.5\');
            svg.appendChild(line);
        }
    }
    
    // Ejes
    const axes = document.createElementNS(\'http://www.w3.org/2000/svg\', \'g\');
    axes.setAttribute(\'stroke\', \'#555\');
    axes.setAttribute(\'stroke-width\', \'1\');
    
    const xAxis = document.createElementNS(\'http://www.w3.org/2000/svg\', \'line\');
    xAxis.setAttribute(\'x1\', \'50\');
    xAxis.setAttribute(\'y1\', centerY);
    xAxis.setAttribute(\'x2\', \'350\');
    xAxis.setAttribute(\'y2\', centerY);
    axes.appendChild(xAxis);
    
    const yAxis = document.createElementNS(\'http://www.w3.org/2000/svg\', \'line\');
    yAxis.setAttribute(\'x1\', centerX);
    yAxis.setAttribute(\'y1\', \'50\');
    yAxis.setAttribute(\'x2\', centerX);
    yAxis.setAttribute(\'y2\', \'250\');
    axes.appendChild(yAxis);
    
    svg.appendChild(axes);
    
    // Representar orbital según tipo
    switch(orbitalType) {
        case \'1s\':
            drawSphericalOrbital(svg, centerX, centerY, probRadius, data.color, showPhase);
            break;
        case \'2pz\':
            drawDumbbellOrbital(svg, centerX, centerY, probRadius, data.color, showPhase);
            break;
        case \'3dxy\':
            drawCloverleafOrbital(svg, centerX, centerY, probRadius, data.color, showPhase);
            break;
        case \'4f\':
            drawComplexOrbital(svg, centerX, centerY, probRadius, data.color, showPhase);
            break;
    }
    
    // Mostrar nodos si está activado
    if (showNodes && data.nodes.angular > 0) {
        drawNodes(svg, centerX, centerY, baseRadius, data.nodes.angular, orbitalType);
    }
    
    // Marcar actividad completada
    markActivityCompleted(\'orbital-simulator\');
}

function drawSphericalOrbital(svg, cx, cy, radius, color, showPhase) {
    const sphere = document.createElementNS(\'http://www.w3.org/2000/svg\', \'circle\');
    sphere.setAttribute(\'cx\', cx);
    sphere.setAttribute(\'cy\', cy);
    sphere.setAttribute(\'r\', radius);
    sphere.setAttribute(\'fill\', color);
    sphere.setAttribute(\'opacity\', \'0.6\');
    sphere.setAttribute(\'filter\', \'url(#glow)\');
    svg.appendChild(sphere);
    
    // Crear filtro de brillo si no existe
    if (!document.getElementById(\'glow-filter\')) {
        const defs = document.createElementNS(\'http://www.w3.org/2000/svg\', \'defs\');
        const filter = document.createElementNS(\'http://www.w3.org/2000/svg\', \'filter\');
        filter.id = \'glow\';
        
        const feGaussianBlur = document.createElementNS(\'http://www.w3.org/2000/svg\', \'feGaussianBlur\');
        feGaussianBlur.setAttribute(\'stdDeviation\', \'3\');
        feGaussianBlur.setAttribute(\'result\', \'coloredBlur\');
        
        const feMerge = document.createElementNS(\'http://www.w3.org/2000/svg\', \'feMerge\');
        const feMergeNode1 = document.createElementNS(\'http://www.w3.org/2000/svg\', \'feMergeNode\');
        feMergeNode1.setAttribute(\'in\', \'coloredBlur\');
        const feMergeNode2 = document.createElementNS(\'http://www.w3.org/2000/svg\', \'feMergeNode\');
        feMergeNode2.setAttribute(\'in\', \'SourceGraphic\');
        
        feMerge.appendChild(feMergeNode1);
        feMerge.appendChild(feMergeNode2);
        
        filter.appendChild(feGaussianBlur);
        filter.appendChild(feMerge);
        defs.appendChild(filter);
        svg.appendChild(defs);
    }
}

function drawDumbbellOrbital(svg, cx, cy, radius, color, showPhase) {
    // Lóbulo positivo (arriba)
    const lobe1 = document.createElementNS(\'http://www.w3.org/2000/svg\', \'ellipse\');
    lobe1.setAttribute(\'cx\', cx);
    lobe1.setAttribute(\'cy\', cy - radius * 0.7);
    lobe1.setAttribute(\'rx\', radius * 0.5);
    lobe1.setAttribute(\'ry\', radius * 0.3);
    lobe1.setAttribute(\'fill\', showPhase ? color : \'#00aaff\');
    lobe1.setAttribute(\'opacity\', \'0.7\');
    svg.appendChild(lobe1);
    
    // Lóbulo negativo (abajo)
    const lobe2 = document.createElementNS(\'http://www.w3.org/2000/svg\', \'ellipse\');
    lobe2.setAttribute(\'cx\', cx);
    lobe2.setAttribute(\'cy\', cy + radius * 0.7);
    lobe2.setAttribute(\'rx\', radius * 0.5);
    lobe2.setAttribute(\'ry\', radius * 0.3);
    lobe2.setAttribute(\'fill\', showPhase ? \'#ff00aa\' : \'#00aaff\');
    lobe2.setAttribute(\'opacity\', \'0.7\');
    svg.appendChild(lobe2);
    
    // Nodo (plano)
    if (showPhase) {
        const node = document.createElementNS(\'http://www.w3.org/2000/svg\', \'line\');
        node.setAttribute(\'x1\', cx - radius);
        node.setAttribute(\'y1\', cy);
        node.setAttribute(\'x2\', cx + radius);
        node.setAttribute(\'y2\', cy);
        node.setAttribute(\'stroke\', \'#fff\');
        node.setAttribute(\'stroke-width\', \'1\');
        node.setAttribute(\'stroke-dasharray\', \'5,5\');
        node.setAttribute(\'opacity\', \'0.5\');
        svg.appendChild(node);
    }
}

function drawCloverleafOrbital(svg, cx, cy, radius, color, showPhase) {
    // Cuatro lóbulos en forma de trébol
    const lobes = 4;
    for (let i = 0; i < lobes; i++) {
        const angle = (i * 90) * Math.PI / 180;
        const lobeX = cx + Math.cos(angle) * radius * 0.6;
        const lobeY = cy + Math.sin(angle) * radius * 0.6;
        
        const lobe = document.createElementNS(\'http://www.w3.org/2000/svg\', \'ellipse\');
        lobe.setAttribute(\'cx\', lobeX);
        lobe.setAttribute(\'cy\', lobeY);
        lobe.setAttribute(\'rx\', radius * 0.4);
        lobe.setAttribute(\'ry\', radius * 0.2);
        lobe.setAttribute(\'fill\', (i % 2 === 0 && showPhase) ? color : \'#ff00aa\');
        lobe.setAttribute(\'opacity\', \'0.7\');
        lobe.setAttribute(\'transform\', `rotate(${angle * 180 / Math.PI + 45}, ${lobeX}, ${lobeY})`);
        svg.appendChild(lobe);
    }
    
    // Nodos
    if (showPhase) {
        // Nodo vertical
        const node1 = document.createElementNS(\'http://www.w3.org/2000/svg\', \'line\');
        node1.setAttribute(\'x1\', cx);
        node1.setAttribute(\'y1\', cy - radius);
        node1.setAttribute(\'x2\', cx);
        node1.setAttribute(\'y2\', cy + radius);
        node1.setAttribute(\'stroke\', \'#fff\');
        node1.setAttribute(\'stroke-width\', \'1\');
        node1.setAttribute(\'stroke-dasharray\', \'5,5\');
        node1.setAttribute(\'opacity\', \'0.5\');
        svg.appendChild(node1);
        
        // Nodo horizontal
        const node2 = document.createElementNS(\'http://www.w3.org/2000/svg\', \'line\');
        node2.setAttribute(\'x1\', cx - radius);
        node2.setAttribute(\'y1\', cy);
        node2.setAttribute(\'x2\', cx + radius);
        node2.setAttribute(\'y2\', cy);
        node2.setAttribute(\'stroke\', \'#fff\');
        node2.setAttribute(\'stroke-width\', \'1\');
        node2.setAttribute(\'stroke-dasharray\', \'5,5\');
        node2.setAttribute(\'opacity\', \'0.5\');
        svg.appendChild(node2);
    }
}

function drawComplexOrbital(svg, cx, cy, radius, color, showPhase) {
    // Ocho lóbulos complejos
    const lobes = 8;
    for (let i = 0; i < lobes; i++) {
        const angle = (i * 45) * Math.PI / 180;
        const distance = radius * (i % 2 === 0 ? 0.7 : 0.4);
        const lobeX = cx + Math.cos(angle) * distance;
        const lobeY = cy + Math.sin(angle) * distance;
        
        const lobe = document.createElementNS(\'http://www.w3.org/2000/svg\', \'circle\');
        lobe.setAttribute(\'cx\', lobeX);
        lobe.setAttribute(\'cy\', lobeY);
        lobe.setAttribute(\'r\', radius * 0.15);
        lobe.setAttribute(\'fill\', (i < 4 && showPhase) ? color : \'#ff00aa\');
        lobe.setAttribute(\'opacity\', \'0.6\');
        svg.appendChild(lobe);
    }
}

function drawNodes(svg, cx, cy, radius, nodeCount, orbitalType) {
    for (let i = 0; i < nodeCount; i++) {
        const angle = (i * 180 / nodeCount) * Math.PI / 180;
        const node = document.createElementNS(\'http://www.w3.org/2000/svg\', \'line\');
        
        if (orbitalType === \'2pz\') {
            // Nodo horizontal para pz
            node.setAttribute(\'x1\', cx - radius);
            node.setAttribute(\'y1\', cy);
            node.setAttribute(\'x2\', cx + radius);
            node.setAttribute(\'y2\', cy);
        } else {
            // Nodos radiales para otros orbitales
            const x1 = cx + Math.cos(angle) * radius;
            const y1 = cy + Math.sin(angle) * radius;
            const x2 = cx - Math.cos(angle) * radius;
            const y2 = cy - Math.sin(angle) * radius;
            
            node.setAttribute(\'x1\', x1);
            node.setAttribute(\'y1\', y1);
            node.setAttribute(\'x2\', x2);
            node.setAttribute(\'y2\', y2);
        }
        
        node.setAttribute(\'stroke\', \'#fff\');
        node.setAttribute(\'stroke-width\', \'1\');
        node.setAttribute(\'stroke-dasharray\', \'5,5\');
        node.setAttribute(\'opacity\', \'0.3\');
        svg.appendChild(node);
    }
}

// ========== SIMULADOR DE ESPECTRO ATÓMICO ==========
function calculateSpectralLine() {
    const ni = parseInt(document.getElementById(\'initial-level\').value);
    const nf = parseInt(document.getElementById(\'final-level\').value);
    
    if (ni <= nf) {
        alert(\'❌ El nivel inicial debe ser MAYOR que el nivel final\');
        return;
    }
    
    // Fórmula de Rydberg para el hidrógeno
    const R = PHYSICS_CONSTANTS.R; // m⁻¹
    const wavelengthMeters = 1 / (R * (1/(nf*nf) - 1/(ni*ni)));
    const wavelengthNM = wavelengthMeters * 1e9; // Convertir a nm
    
    // Energía del fotón
    const energyJoules = (PHYSICS_CONSTANTS.h * PHYSICS_CONSTANTS.c) / wavelengthMeters;
    const energyEV = energyJoules / PHYSICS_CONSTANTS.e;
    
    // Determinar serie y región
    let series = \'\', region = \'\', colorName = \'\';
    if (nf === 1) {
        series = \'Lyman\';
        region = \'Ultravioleta\';
        colorName = \'UV\';
    } else if (nf === 2) {
        series = \'Balmer\';
        region = \'Visible\';
        // Determinar color aproximado
        if (wavelengthNM < 450) colorName = \'violeta\';
        else if (wavelengthNM < 485) colorName = \'azul\';
        else if (wavelengthNM < 500) colorName = \'cian\';
        else if (wavelengthNM < 565) colorName = \'verde\';
        else if (wavelengthNM < 590) colorName = \'amarillo\';
        else if (wavelengthNM < 625) colorName = \'naranja\';
        else colorName = \'rojo\';
    } else if (nf === 3) {
        series = \'Paschen\';
        region = \'Infrarrojo\';
        colorName = \'IR\';
    }
    
    // Actualizar display
    document.getElementById(\'wavelength\').textContent = wavelengthNM.toFixed(1) + \' nm\';
    document.getElementById(\'photon-energy\').textContent = energyEV.toFixed(2) + \' eV\';
    document.getElementById(\'series\').textContent = series;
    document.getElementById(\'region\').textContent = region;
    document.getElementById(\'color-indicator\').textContent = `(${colorName})`;
    
    // Actualizar línea espectral
    const line = document.getElementById(\'spectrum-line\');
    const color = wavelengthToColor(wavelengthNM);
    line.style.backgroundColor = color;
    line.style.width = \'100%\';
    line.style.height = \'30px\';
    line.style.borderRadius = \'15px\';
    line.style.opacity = \'0.8\';
    line.style.boxShadow = `0 0 10px ${color}`;
    
    // Mostrar información adicional
    const transitionInfo = `Transición: n=${ni} → n=${nf}\\nEnergía: ${energyEV.toFixed(2)} eV\\nλ: ${wavelengthNM.toFixed(1)} nm`;
    line.title = transitionInfo;
    
    // Marcar actividad completada
    markActivityCompleted(\'spectrum-simulator\');
}

// ========== CONSTRUCTOR DE ÁTOMOS ==========
function updateAtomBuilder() {
    const Z = parseInt(document.getElementById(\'z-slider\').value);
    const element = ELEMENTS[Z - 1];
    
    // Actualizar información básica
    document.getElementById(\'atomic-number\').textContent = Z;
    document.getElementById(\'config-display\').textContent = element.config;
    document.getElementById(\'element-name\').textContent = element.name;
    document.getElementById(\'element-symbol\').textContent = element.symbol;
    document.getElementById(\'element-block\').textContent = element.block;
    document.getElementById(\'valence-electrons\').textContent = element.valence;
    document.getElementById(\'period\').textContent = element.period;
    document.getElementById(\'group\').textContent = element.group;
    
    // Actualizar diagrama de orbitales
    updateOrbitalDiagram(Z);
    
    // Marcar actividad completada
    markActivityCompleted(\'atom-builder\');
}

function updateOrbitalDiagram(Z) {
    const diagram = document.getElementById(\'orbital-diagram\');
    diagram.innerHTML = \'\';
    
    // Configuración de orbitales en orden de llenado
    const orbitalOrder = [
        {label: \'1s\', max: 2, type: \'s\'},
        {label: \'2s\', max: 2, type: \'s\'},
        {label: \'2p\', max: 6, type: \'p\'},
        {label: \'3s\', max: 2, type: \'s\'},
        {label: \'3p\', max: 6, type: \'p\'},
        {label: \'4s\', max: 2, type: \'s\'},
        {label: \'3d\', max: 10, type: \'d\'},
        {label: \'4p\', max: 6, type: \'p\'}
    ];
    
    let remainingElectrons = Z;
    let currentLevel = 1;
    
    orbitalOrder.forEach(orbital => {
        const container = document.createElement(\'div\');
        container.className = \'orbital-row\';
        
        const label = document.createElement(\'div\');
        label.className = \'orbital-label\';
        label.textContent = orbital.label;
        label.style.color = getOrbitalColor(orbital.type);
        container.appendChild(label);
        
        const boxes = document.createElement(\'div\');
        boxes.className = \'orbital-boxes\';
        
        const electronsInOrbital = Math.min(remainingElectrons, orbital.max);
        remainingElectrons -= electronsInOrbital;
        
        // Determinar electrones desapareados (regla de Hund)
        let unpaired = 0;
        let boxesPerSubshell = orbital.max;
        
        if (orbital.type === \'p\') {
            boxesPerSubshell = 3; // 3 orbitales p
            if (electronsInOrbital > 0 && electronsInOrbital < orbital.max) {
                unpaired = electronsInOrbital <= 3 ? electronsInOrbital : 6 - electronsInOrbital;
            }
        } else if (orbital.type === \'d\') {
            boxesPerSubshell = 5; // 5 orbitales d
            if (electronsInOrbital > 0 && electronsInOrbital < orbital.max) {
                unpaired = electronsInOrbital <= 5 ? electronsInOrbital : 10 - electronsInOrbital;
            }
        }
        
        // Crear casillas
        for (let i = 0; i < boxesPerSubshell; i++) {
            const boxContainer = document.createElement(\'div\');
            boxContainer.style.display = \'flex\';
            boxContainer.style.flexDirection = \'column\';
            boxContainer.style.gap = \'2px\';
            
            // Casilla para espín up
            const boxUp = document.createElement(\'div\');
            boxUp.className = \'electron-box\';
            
            // Casilla para espín down (solo si es orbital s)
            const boxDown = document.createElement(\'div\');
            boxDown.className = \'electron-box\';
            
            // Calcular cuántos electrones hay en este orbital específico
            let electronsInThisOrbital = 0;
            let hasUp = false;
            let hasDown = false;
            
            if (orbital.type === \'s\') {
                // Orbital s solo tiene uno
                if (electronsInOrbital > 0) {
                    boxUp.innerHTML = \'↑\';
                    boxUp.classList.add(\'filled\', \'spin-up\');
                    if (electronsInOrbital > 1) {
                        boxDown.innerHTML = \'↓\';
                        boxDown.classList.add(\'filled\', \'spin-down\');
                    }
                }
            } else {
                // Orbitales p y d
                const maxPerBox = 2;
                let electronsAssigned = 0;
                
                for (let boxIndex = 0; boxIndex < boxesPerSubshell; boxIndex++) {
                    const available = Math.min(orbital.max - electronsAssigned, maxPerBox);
                    const toAssign = Math.min(electronsInOrbital - electronsAssigned, available);
                    
                    if (boxIndex === i) {
                        if (toAssign > 0) {
                            boxUp.innerHTML = \'↑\';
                            boxUp.classList.add(\'filled\', \'spin-up\');
                            if (toAssign > 1) {
                                boxDown.innerHTML = \'↓\';
                                boxDown.classList.add(\'filled\', \'spin-down\');
                            } else {
                                boxUp.classList.add(\'unpaired\');
                            }
                        }
                        break;
                    }
                    electronsAssigned += toAssign;
                }
            }
            
            boxContainer.appendChild(boxUp);
            if (orbital.type !== \'s\') {
                boxContainer.appendChild(boxDown);
            }
            boxes.appendChild(boxContainer);
        }
        
        container.appendChild(boxes);
        
        // Solo mostrar si hay electrones o es el siguiente nivel
        if (electronsInOrbital > 0 || currentLevel <= Math.ceil(Z/2)) {
            diagram.appendChild(container);
        }
        
        currentLevel++;
    });
}

function getOrbitalColor(type) {
    switch(type) {
        case \'s\': return \'#00ff88\';
        case \'p\': return \'#ff5500\';
        case \'d\': return \'#aa00ff\';
        case \'f\': return \'#00aaff\';
        default: return \'#ffffff\';
    }
}

// ========== PRINCIPIO DE INCERTIDUMBRE ==========
function updateUncertaintySimulation() {
    const dx = parseFloat(document.getElementById(\'dx-slider\').value); // en nm
    const dxMeters = dx * 1e-9; // Convertir a metros
    
    // Calcular Δp mínimo según Heisenberg
    const dpMin = PHYSICS_CONSTANTS.ħ / (2 * dxMeters);
    
    // Actualizar valores
    document.getElementById(\'dx-value\').textContent = dx.toFixed(1) + \' nm\';
    document.getElementById(\'dp-value\').textContent = formatScientific(dpMin, 2) + \' kg·m/s\';
    
    // Calcular producto
    const product = dxMeters * dpMin;
    const productFormatted = formatScientific(product, 2);
    document.getElementById(\'uncertainty-product\').textContent = productFormatted;
    
    // Actualizar valor del límite de Heisenberg
    const heisenbergLimit = PHYSICS_CONSTANTS.ħ / 2;
    document.getElementById(\'heisenberg-value\').textContent = formatScientific(heisenbergLimit, 2);
    
    // Actualizar barra de incertidumbre
    const ratio = product / heisenbergLimit;
    const fillWidth = Math.min(Math.max((ratio - 0.5) * 100, 0), 100);
    
    const fillElement = document.getElementById(\'uncertainty-fill\');
    fillElement.style.width = fillWidth + \'%\';
    
    // Color según la región
    if (ratio < 1) {
        fillElement.style.backgroundColor = \'#ff4444\'; // Imposible (viola principio)
        fillElement.style.opacity = \'0.3\';
    } else if (ratio < 2) {
        fillElement.style.backgroundColor = \'#00ff88\'; // Límite cuántico
        fillElement.style.opacity = \'0.8\';
    } else {
        fillElement.style.backgroundColor = \'#00aaff\'; // Región clásica
        fillElement.style.opacity = \'0.6\';
    }
    
    // Actualizar slider de Δp (solo visual)
    const dpSlider = document.getElementById(\'dp-slider\');
    const dpValue = Math.min(Math.max(dpMin / 1e-25, 0.1), 10);
    dpSlider.value = dpValue.toFixed(1);
    
    // Marcar actividad completada
    markActivityCompleted(\'uncertainty-simulator\');
}

// ========== ERRORES COMUNES INTERACTIVOS ==========
function setupErrorDetails() {
    document.querySelectorAll(\'.error-detail\').forEach(button => {
        button.addEventListener(\'click\', function() {
            const errorId = this.getAttribute(\'data-error\');
            const explanation = document.getElementById(\'error-\' + errorId);
            
            if (explanation.style.display === \'block\') {
                explanation.style.display = \'none\';
                this.textContent = \'Ver explicación detallada\';
                this.classList.remove(\'active\');
            } else {
                // Cerrar otras explicaciones
                document.querySelectorAll(\'.error-explanation\').forEach(el => {
                    el.style.display = \'none\';
                });
                document.querySelectorAll(\'.error-detail\').forEach(btn => {
                    btn.textContent = \'Ver explicación detallada\';
                    btn.classList.remove(\'active\');
                });
                
                // Mostrar esta explicación
                explanation.style.display = \'block\';
                this.textContent = \'Ocultar explicación\';
                this.classList.add(\'active\');
            }
        });
    });
}

// ========== QUIZ DE ERRORES COMUNES ==========
function setupErrorQuiz() {
    document.querySelectorAll(\'.quiz-option\').forEach(button => {
        button.addEventListener(\'click\', function() {
            const isCorrect = this.getAttribute(\'data-correct\') === \'true\';
            const quizItem = this.closest(\'.quiz-item\');
            const feedback = quizItem.querySelector(\'.quiz-feedback\');
            
            // Deshabilitar todos los botones en este ítem
            quizItem.querySelectorAll(\'.quiz-option\').forEach(btn => {
                btn.disabled = true;
            });
            
            // Mostrar feedback
            if (isCorrect) {
                this.classList.add(\'correct\');
                feedback.innerHTML = \'✅ Correcto! Excelente comprensión.\';
                feedback.style.color = \'#00ff88\';
                learningStats.conceptsMastered++;
            } else {
                this.classList.add(\'incorrect\');
                feedback.innerHTML = \'❌ Incorrecto. Revisa la sección de errores comunes.\';
                feedback.style.color = \'#ff4444\';
            }
            
            updateLearningStats();
        });
    });
}

// ========== VERIFICADOR DE PROBLEMAS ==========
function setupProblemCheckers() {
    document.querySelectorAll(\'.check-answer\').forEach(button => {
        button.addEventListener(\'click\', function() {
            const problemNum = this.getAttribute(\'data-problem\');
            const hint = this.nextElementSibling;
            
            // Mostrar pistas según el problema
            const hints = {
                1: \'📝 Pistas: 1) Rutherford no explicaba espectros, 2) Órbitas no eran elípticas en Bohr, 3) Bohr asumía trayectorias definidas.\',
                2: \'📝 Pistas: A: Cr [Ar]4s¹3d⁵, B: Cu [Ar]4s¹3d¹⁰, C: Zn [Ar]4s²3d¹⁰. El radio aumenta hacia abajo y izquierda.\',
                3: \'📝 Pistas: n=3, l=2, m=±2. Forma de rosetón. Principio incertidumbre: precisión posición vs momento. Energía depende de n principalmente.\'
            };
            
            hint.innerHTML = hints[problemNum] || \'💡 Revisa los conceptos clave de la lección.\';
            hint.style.display = \'block\';
            
            // Marcar problema como trabajado
            learningStats.problemsSolved++;
            updateLearningStats();
        });
    });
}

// ========== GENERADOR DE PLAN DE ESTUDIO ==========
function generateStudyPlan() {
    // Ocultar todas las sugerencias primero
    document.querySelectorAll(\'.suggestion\').forEach(el => {
        el.style.display = \'none\';
    });
    
    // Calcular puntaje basado en actividades completadas
    const completed = learningStats.completedActivities.size;
    const totalActivities = 5; // orbital, spectrum, atom, uncertainty, quiz
    const score = (completed / totalActivities) * 100;
    
    // Mostrar sugerencia apropiada
    let suggestionId;
    if (score < 40) {
        suggestionId = \'suggestion-basic\';
    } else if (score < 70) {
        suggestionId = \'suggestion-intermediate\';
    } else {
        suggestionId = \'suggestion-advanced\';
    }
    
    const suggestion = document.getElementById(suggestionId);
    suggestion.style.display = \'block\';
    
    // Mensaje personalizado
    const messages = [
        "¡Excelente progreso! Dominas los conceptos avanzados.",
        "Buen trabajo. Continúa practicando para consolidar.",
        "Hay conceptos por reforzar. La práctica constante es clave."
    ];
    
    const messageIndex = Math.floor((score / 100) * messages.length);
    alert(`📊 Tu puntaje: ${Math.round(score)}%

${messages[messageIndex]}

Se ha generado tu plan de estudio personalizado.`);
}

// ========== GESTIÓN DE ESTADÍSTICAS ==========
function markActivityCompleted(activityId) {
    if (!learningStats.completedActivities.has(activityId)) {
        learningStats.completedActivities.add(activityId);
        learningStats.simulatorsCompleted = learningStats.completedActivities.size;
        updateLearningStats();
    }
}

function updateLearningStats() {
    // Actualizar estadísticas
    document.getElementById(\'concepts-mastered\').textContent = learningStats.conceptsMastered;
    document.getElementById(\'simulators-completed\').textContent = learningStats.simulatorsCompleted;
    document.getElementById(\'problems-solved\').textContent = learningStats.problemsSolved;
    
    // Calcular tiempo de estudio
    const elapsedMinutes = Math.floor((Date.now() - learningStats.startTime) / 60000);
    document.getElementById(\'learning-time\').textContent = `${elapsedMinutes} min`;
    
    // Calcular progreso general
    const totalScore = 
        (learningStats.conceptsMastered * 10) + 
        (learningStats.simulatorsCompleted * 15) + 
        (learningStats.problemsSolved * 20);
    const maxScore = (4 * 10) + (5 * 15) + (3 * 20); // 4 conceptos, 5 simuladores, 3 problemas
    const progressPercent = Math.min(Math.round((totalScore / maxScore) * 100), 100);
    
    document.getElementById(\'progress-percent\').textContent = `${progressPercent}%`;
    document.getElementById(\'progress-fill\').style.width = `${progressPercent}%`;
}

// ========== INICIALIZACIÓN ==========
document.addEventListener(\'DOMContentLoaded\', function() {
    // Inicializar simuladores
    updateOrbitalVisualization();
    updateAtomBuilder();
    updateUncertaintySimulation();
    
    // Configurar event listeners para orbitales
    document.getElementById(\'orbital-type\').addEventListener(\'change\', updateOrbitalVisualization);
    document.getElementById(\'probability-slider\').addEventListener(\'input\', function() {
        document.getElementById(\'prob-value\').textContent = this.value + \'%\';
        updateOrbitalVisualization();
    });
    document.getElementById(\'show-nodes\').addEventListener(\'change\', updateOrbitalVisualization);
    document.getElementById(\'show-phase\').addEventListener(\'change\', updateOrbitalVisualization);
    document.getElementById(\'show-grid\').addEventListener(\'change\', updateOrbitalVisualization);
    
    // Configurar espectro atómico
    document.getElementById(\'calculate-transition\').addEventListener(\'click\', calculateSpectralLine);
    document.getElementById(\'initial-level\').addEventListener(\'change\', calculateSpectralLine);
    document.getElementById(\'final-level\').addEventListener(\'change\', calculateSpectralLine);
    
    // Configurar constructor de átomos
    document.getElementById(\'z-slider\').addEventListener(\'input\', updateAtomBuilder);
    
    // Configurar principio de incertidumbre
    document.getElementById(\'dx-slider\').addEventListener(\'input\', updateUncertaintySimulation);
    
    // Configurar errores comunes
    setupErrorDetails();
    setupErrorQuiz();
    
    // Configurar verificadores de problemas
    setupProblemCheckers();
    
    // Configurar generador de plan
    document.getElementById(\'generate-plan\').addEventListener(\'click\', generateStudyPlan);
    
    // Configurar guardado de reflexión
    document.getElementById(\'save-reflection\').addEventListener(\'click\', function() {
        alert(\'💾 Tu reflexión ha sido guardada (en un sistema real se enviaría al servidor).\');
        learningStats.conceptsMastered = Math.min(learningStats.conceptsMastered + 1, 4);
        updateLearningStats();
    });
    
    // Inicializar estadísticas
    updateLearningStats();
    
    // Configurar MathJax para actualizar ecuaciones
    if (window.MathJax) {
        MathJax.typesetPromise();
    }
    
    // Efecto de scroll suave para enlaces internos
    document.querySelectorAll(\'.resource-link\').forEach(link => {
        link.addEventListener(\'click\', function(e) {
            e.preventDefault();
            // En un sistema real, aquí iría la navegación
            alert(\'🔗 En un sistema real, este enlace te llevaría al recurso correspondiente.\');
        });
    });
    
    // Efectos visuales adicionales
    document.querySelectorAll(\'.lab-button, .action-button\').forEach(button => {
        button.addEventListener(\'mouseenter\', function() {
            this.style.transform = \'translateY(-2px)\';
        });
        button.addEventListener(\'mouseleave\', function() {
            this.style.transform = \'translateY(0)\';
        });
    });
    
    // Actualizar estadísticas periódicamente
    setInterval(updateLearningStats, 30000); // Cada 30 segundos
});

// Configurar arrastre de electrones (interactividad adicional)
function setupElectronDrag() {
    document.querySelectorAll(\'.electron-box\').forEach(box => {
        box.addEventListener(\'mousedown\', function(e) {
            if (!this.classList.contains(\'filled\')) return;
            
            const originalBox = this;
            const clone = originalBox.cloneNode(true);
            clone.style.position = \'absolute\';
            clone.style.zIndex = \'1000\';
            clone.style.pointerEvents = \'none\';
            document.body.appendChild(clone);
            
            function moveAt(pageX, pageY) {
                clone.style.left = pageX - clone.offsetWidth / 2 + \'px\';
                clone.style.top = pageY - clone.offsetHeight / 2 + \'px\';
            }
            
            moveAt(e.pageX, e.pageY);
            
            function onMouseMove(event) {
                moveAt(event.pageX, event.pageY);
            }
            
            document.addEventListener(\'mousemove\', onMouseMove);
            
            originalBox.onmouseup = function() {
                document.removeEventListener(\'mousemove\', onMouseMove);
                clone.remove();
                originalBox.onmouseup = null;
            };
        });
    });
}

// En la función updateAtomBuilder, llama a setupElectronDrag después de actualizar
function updateAtomBuilder() {
    const Z = parseInt(document.getElementById(\'z-slider\').value);
    const element = ELEMENTS[Z - 1];
    
    // Actualizar información básica
    document.getElementById(\'atomic-number\').textContent = Z;
    document.getElementById(\'config-display\').textContent = element.config;
    document.getElementById(\'element-name\').textContent = element.name;
    document.getElementById(\'element-symbol\').textContent = element.symbol;
    document.getElementById(\'element-block\').textContent = element.block;
    document.getElementById(\'valence-electrons\').textContent = element.valence;
    document.getElementById(\'period\').textContent = element.period;
    document.getElementById(\'group\').textContent = element.group;
    
    // Actualizar diagrama de orbitales
    updateOrbitalDiagram(Z);
    
    // Configurar arrastre de electrones
    setTimeout(setupElectronDrag, 100);
    
    // Marcar actividad completada
    markActivityCompleted(\'atom-builder\');
}

// Agrega esta función para tooltips
function setupTooltips() {
    document.querySelectorAll(\'.electron-box\').forEach(box => {
        box.addEventListener(\'mouseenter\', function() {
            if (this.classList.contains(\'filled\')) {
                const spin = this.classList.contains(\'spin-up\') ? \'+½\' : \'-½\';
                const orbital = this.closest(\'.orbital-row\').querySelector(\'.orbital-label\').textContent;
                this.title = `Orbital: $\\{orbital}
Spin: ${spin}
${this.classList.contains(\'unpaired\') ? \'Electrón desapareado\' : \'Electrón apareado\'}`;
            }
        });
    });
}

// Y en updateAtomBuilder, después de setupElectronDrag:
setTimeout(setupTooltips, 100);
</script>',
