<!-- 5️⃣ MONITOR CALIDAD AIRE -->
<section id="monitor-aire">
    <h2 class="subtitulo-conceptual">IV. MONITOR DE CALIDAD AIRE</h2>
    
    <div class="air-quality-container">
        <div class="aqi-visual">
