<!-- SCRIPT JAVASCRIPT -->
<script>
// ============================================
// SISTEMA CYBER-QUÍMICA: LÓGICA INTERACTIVA
// ============================================

document.addEventListener(\'DOMContentLoaded\', function() {
    console.log(\'[SISTEMA] Iniciando lección Cyber-Química\');
    console.log(\'[QUÍMICA] Tema: Cambios Químicos y Reacciones\');
    
    inicializarSimulador();
    inicializarQuiz();
    inicializarProblemas();
    inicializarProgreso();
    
    // Configurar MathJax si está disponible
    if (window.MathJax) {
        MathJax.typesetPromise();
    }
});

// ========== SISTEMA DE PROGRESO ==========
let progresoTotal = 0;
const progresoMaximo = 100;

function inicializarProgreso() {
    // Observar scroll para marcar secciones como vistas
    const secciones = document.querySelectorAll(\'.seccion-cyber\');
    const observer = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                const id = entry.target.id;
                if (!localStorage.getItem(`visto_${id}`)) {
                    localStorage.setItem(`visto_${id}`, \'true\');
                    actualizarProgreso(5); // 5% por sección vista
                }
            }
        });
    }, { threshold: 0.5 });
    
    secciones.forEach(seccion => observer.observe(seccion));
    
    // Recuperar progreso guardado
    const progresoGuardado = localStorage.getItem(\'progreso_quimica\');
    if (progresoGuardado) {
        progresoTotal = parseInt(progresoGuardado);
        actualizarDisplayProgreso();
    }
}

function actualizarProgreso(puntos) {
    progresoTotal = Math.min(progresoMaximo, progresoTotal + puntos);
    
    // Actualizar displays
    document.getElementById(\'progreso-global\').textContent = `${progresoTotal}%`;
    document.getElementById(\'progreso-final\').textContent = `${progresoTotal}%`;
    
    // Actualizar barra de progreso
    const barra = document.getElementById(\'barra-progreso-total\');
    if (barra) {
        barra.style.width = `${progresoTotal}%`;
    }
    
    // Actualizar barras de objetivos
    actualizarProgresoObjetivos();
    
    // Guardar en localStorage
    localStorage.setItem(\'progreso_quimica\', progresoTotal);
    
    console.log(`[PROGRESO] Actualizado: ${progresoTotal}% (+${puntos})`);
}

function actualizarDisplayProgreso() {
    const elementos = [\'progreso-global\', \'progreso-final\'];
    elementos.forEach(id => {
        const elemento = document.getElementById(id);
        if (elemento) {
            elemento.textContent = `${progresoTotal}%`;
        }
    });
    
    const barra = document.getElementById(\'barra-progreso-total\');
    if (barra) {
        barra.style.width = `${progresoTotal}%`;
    }
}

function actualizarProgresoObjetivos() {
    const objetivos = document.querySelectorAll(\'.objetivo-progreso .progreso-bar\');
    objetivos.forEach((barra, index) => {
        const progreso = Math.min(100, (progresoTotal / 4) + (index * 10));
        barra.style.width = `${progreso}%`;
    });
}

// ========== SIMULADOR ==========
let simuladorIntervalo = null;
let tiempoSimulacion = 0;
let simuladorActivo = false;

function inicializarSimulador() {
    // Configurar sliders
    const sliderTemp = document.getElementById(\'temperatura-slider\');
    const sliderConc = document.getElementById(\'concentracion-slider\');
    
    if (sliderTemp) {
        sliderTemp.addEventListener(\'input\', function() {
            document.getElementById(\'temp-valor\').textContent = `${this.value}°C`;
        });
    }
    
    if (sliderConc) {
        sliderConc.addEventListener(\'input\', function() {
            document.getElementById(\'conc-valor\').textContent = `${this.value}%`;
        });
    }
    
    // Configurar botones de tipo
    document.querySelectorAll(\'.tipo-btn\').forEach(btn => {
        btn.addEventListener(\'click\', function() {
            document.querySelectorAll(\'.tipo-btn\').forEach(b => b.classList.remove(\'active\'));
            this.classList.add(\'active\');
            actualizarEcuacionSimulador();
        });
    });
    
    // Configurar selector de reactivo
    document.getElementById(\'reactivo-select\').addEventListener(\'change\', actualizarEcuacionSimulador);
}

function iniciarSimulacion() {
    if (simuladorActivo) return;
    
    simuladorActivo = true;
    tiempoSimulacion = 0;
    
    const reactivo = document.getElementById(\'reactivo-select\').value;
    const temperatura = document.getElementById(\'temperatura-slider\').value;
    const concentracion = document.getElementById(\'concentracion-slider\').value;
    const tipoBtn = document.querySelector(\'.tipo-btn.active\');
    const tipo = tipoBtn ? tipoBtn.dataset.tipo : \'combustion\';
    
    console.log(`[SIMULADOR] Iniciando: ${reactivo}, ${temperatura}°C, ${concentracion}%, ${tipo}`);
    agregarLogSimulador(\'Reacción iniciada\');
    
    // Actualizar visualización
    actualizarVisualizacionSimulador(reactivo, tipo);
    
    // Iniciar intervalo de actualización
    simuladorIntervalo = setInterval(() => {
        if (!simuladorActivo) return;
        
        tiempoSimulacion++;
        
        // Calcular valores
        const progreso = Math.min(100, tiempoSimulacion * 10);
        const energia = Math.min(1000, tiempoSimulacion * 100);
        const velocidad = Math.min(50, tiempoSimulacion * 2);
        
        // Actualizar displays
        document.getElementById(\'tiempo-reaccion\').textContent = `${tiempoSimulacion}s`;
        document.getElementById(\'productos-formados\').textContent = `${progreso}%`;
        document.getElementById(\'energia-liberada\').textContent = `${energia} kJ`;
        document.getElementById(\'velocidad-reaccion\').textContent = `${velocidad} M/s`;
        
        // Actualizar barras
        document.getElementById(\'barra-productos\').style.width = `${progreso}%`;
        document.getElementById(\'barra-energia\').style.width = `${energia / 10}%`;
        
        // Agregar log periódico
        if (tiempoSimulacion % 5 === 0) {
            agregarLogSimulador(`Progreso: ${progreso}% - Energía: ${energia} kJ`);
        }
        
        // Finalizar simulación
        if (tiempoSimulacion >= 10) {
            pausarSimulacion();
            agregarLogSimulador(\'Reacción completada\');
            actualizarProgreso(10); // 10% por completar simulador
        }
    }, 500);
}

function pausarSimulacion() {
    simuladorActivo = false;
    if (simuladorIntervalo) {
        clearInterval(simuladorIntervalo);
        simuladorIntervalo = null;
    }
    agregarLogSimulador(\'Reacción pausada\');
}

function reiniciarSimulacion() {
    pausarSimulacion();
    tiempoSimulacion = 0;
    
    // Resetear valores
    document.getElementById(\'tiempo-reaccion\').textContent = \'0s\';
    document.getElementById(\'productos-formados\').textContent = \'0%\';
    document.getElementById(\'energia-liberada\').textContent = \'0 kJ\';
    document.getElementById(\'velocidad-reaccion\').textContent = \'0 M/s\';
    document.getElementById(\'barra-productos\').style.width = \'0%\';
    document.getElementById(\'barra-energia\').style.width = \'0%\';
    
    // Resetear visualización
    document.getElementById(\'reaction-viz\').innerHTML = `
        <div class="reaction-placeholder">
            <div class="placeholder-text">
                <span class="placeholder-icono">⚗️</span>
                <p>Sistema reiniciado. Listo para nueva simulación.</p>
            </div>
        </div>
    `;
    
    agregarLogSimulador(\'Sistema reiniciado\');
}

function actualizarEcuacionSimulador() {
    const reactivo = document.getElementById(\'reactivo-select\').value;
    const tipoBtn = document.querySelector(\'.tipo-btn.active\');
    const tipo = tipoBtn ? tipoBtn.dataset.tipo : \'combustion\';
    
    let ecuacion = \'\';
    let descripcion = \'\';
    
    switch(reactivo) {
        case \'metano\':
            ecuacion = \'\\\\[ \\\\ce{CH4 + 2O2 -> CO2 + 2H2O} \\\\]\';
            descripcion = \'Combustión - Exotérmica\';
            break;
        case \'hidrogeno\':
            ecuacion = \'\\\\[ \\\\ce{2H2 + O2 -> 2H2O} \\\\]\';
            descripcion = \'Síntesis - Exotérmica\';
            break;
        case \'magnesio\':
            ecuacion = \'\\\\[ \\\\ce{2Mg + O2 -> 2MgO} \\\\]\';
            descripcion = \'Oxidación - Exotérmica\';
            break;
        case \'acido\':
            ecuacion = \'\\\\[ \\\\ce{HCl + NaOH -> NaCl + H2O} \\\\]\';
            descripcion = \'Neutralización - Exotérmica\';
            break;
    }
    
    document.getElementById(\'ecuacion-actual\').innerHTML = ecuacion;
    document.getElementById(\'reaction-tipo\').textContent = descripcion;
    
    // Reprocesar MathJax
    if (window.MathJax) {
        MathJax.typesetPromise([document.getElementById(\'ecuacion-actual\')]);
    }
}

function actualizarVisualizacionSimulador(reactivo, tipo) {
    const container = document.getElementById(\'reaction-viz\');
    let svg = \'\';
    
    switch(tipo) {
        case \'combustion\':
            svg = `
                <svg width="100%" height="180" viewBox="0 0 300 180">
                    <rect width="300" height="180" fill="#0A0A1A"/>
                    <circle cx="100" cy="90" r="30" fill="#FF4444">
                        <animate attributeName="r" values="30;35;30" dur="1.5s" repeatCount="indefinite"/>
                    </circle>
                    <text x="100" y="95" fill="white" text-anchor="middle" font-size="14">CH₄</text>
                    
                    <circle cx="200" cy="90" r="30" fill="#4444FF">
                        <animate attributeName="r" values="30;35;30" dur="1.5s" begin="0.5s" repeatCount="indefinite"/>
                    </circle>
                    <text x="200" y="95" fill="white" text-anchor="middle" font-size="14">O₂</text>
                    
                    <path d="M130,90 L170,90" stroke="#FFFF00" stroke-width="3" marker-end="url(#arrow)">
                        <animate attributeName="stroke-dashoffset" values="0;40" dur="2s" repeatCount="indefinite"/>
                    </path>
                    
                    <circle cx="250" cy="90" r="30" fill="#44FF44" opacity="0">
                        <animate attributeName="opacity" values="0;1" dur="1s" begin="0.5s" fill="freeze"/>
                    </circle>
