    'contenido' => '<!-- INICIO LECCIÓN CYBERPUNK COMPACTA -->
<div class="leccion-container leccion-quimica-particulas" data-tema="particulas-subatomicas">
    
    <!-- CABECERA COMPACTA -->
    <header class="leccion-header">
        <h1 class="titulo-leccion">
            <span class="icon-tema">⚛️</span>
            PARTÍCULAS SUBATÓMICAS
        </h1>
        <div class="subtitulo">
            El Corazón Cuántico de la Materia
        </div>
        <div class="badges-compactos">
            <span class="badge">NIVEL AVANZADO</span>
            <span class="badge">⏱️ 90 min</span>
            <span class="badge">🎯 1500 XP</span>
        </div>
    </header>

    <!-- PANEL OBJETIVOS COMPACTO -->
    <section class="seccion-compacta objetivos">
        <h2 class="titulo-seccion">
            <span class="icon">🎯</span>
            OBJETIVOS DE APRENDIZAJE
        </h2>
        <div class="grid-objetivos">
            <div class="objetivo-card">
                <div class="objetivo-icon">🔬</div>
                <h3>Dominar partículas fundamentales</h3>
                <p>Protón, neutrón, electrón con precisión NIST 2025</p>
            </div>
            <div class="objetivo-card">
                <div class="objetivo-icon">📜</div>
                <h3>Evolución histórica completa</h3>
                <p>Dalton → Thomson → Rutherford → Bohr → Schrödinger</p>
            </div>
            <div class="objetivo-card">
                <div class="objetivo-icon">🧮</div>
                <h3>Cálculos con isótopos</h3>
                <p>Z, A, neutrones, masa atómica, abundancia</p>
            </div>
            <div class="objetivo-card">
                <div class="objetivo-icon">⚖️</div>
                <h3>Manejo del mol y N<sub>A</sub></h3>
                <p>Cálculos con constante de Avogadro</p>
            </div>
        </div>
    </section>

    <!-- DATOS CLAVE - TABLA COMPACTA -->
    <section class="seccion-compacta datos-clave">
        <h2 class="titulo-seccion">
            <span class="icon">📊</span>
            DATOS NIST 2025 - PRECISIÓN CUÁNTICA
        </h2>
        
        <div class="tabla-compacta-container">
            <table class="tabla-compacta">
                <thead>
                    <tr>
                        <th>PARTÍCULA</th>
                        <th>SÍMBOLO</th>
                        <th>CARGA</th>
                        <th>MASA (u)</th>
                        <th>DESCUBRIMIENTO</th>
                    </tr>
                </thead>
                <tbody>
                    <tr>
                        <td><strong>PROTÓN</strong></td>
                        <td>p⁺</td>
                        <td>+1.602×10⁻¹⁹ C</td>
                        <td>1.00727647</td>
                        <td>Rutherford 1919</td>
                    </tr>
                    <tr>
                        <td><strong>NEUTRÓN</strong></td>
                        <td>n⁰</td>
                        <td>0</td>
                        <td>1.00866492</td>
                        <td>Chadwick 1932</td>
                    </tr>
                    <tr>
                        <td><strong>ELECTRÓN</strong></td>
                        <td>e⁻</td>
                        <td>-1.602×10⁻¹⁹ C</td>
                        <td>0.00054858</td>
                        <td>Thomson 1897</td>
                    </tr>
                </tbody>
            </table>
        </div>
    </section>

    <!-- SIMULADOR INTERACTIVO COMPACTO -->
    <section class="seccion-compacta simulador">
        <h2 class="titulo-seccion">
            <span class="icon">🌀</span>
            SIMULADOR: MODELOS ATÓMICOS
        </h2>
        
        <div class="simulador-compacto">
            <!-- CONTROLES -->
            <div class="controles-simulador">
                <div class="control-group">
                    <label>Modelo:</label>
                    <select id="modeloSelect" class="control-select">
                        <option value="dalton">Dalton (1803)</option>
                        <option value="thomson">Thomson (1897)</option>
                        <option value="rutherford" selected>Rutherford (1911)</option>
                        <option value="bohr">Bohr (1913)</option>
                        <option value="schrodinger">Schrödinger (1926)</option>
                    </select>
                </div>
                
                <div class="control-group">
                    <label>Elemento:</label>
                    <select id="elementoSelect" class="control-select">
                        <option value="H">Hidrógeno (Z=1)</option>
                        <option value="He">Helio (Z=2)</option>
                        <option value="C" selected>Carbono (Z=6)</option>
                        <option value="O">Oxígeno (Z=8)</option>
                    </select>
                </div>
                
                <button class="btn-simular" onclick="simularModelo()">
                    <span class="btn-icon">▶</span> SIMULAR
                </button>
                <button class="btn-reset" onclick="resetSimulacion()">
                    <span class="btn-icon">🔄</span> REINICIAR
                </button>
            </div>
            
            <!-- VISUALIZACIÓN -->
            <div class="visualizacion-atomo">
                <svg viewBox="0 0 400 300" id="svgAtomo">
                    <defs>
                        <radialGradient id="gradNucleo">
                            <stop offset="0%" stop-color="#FF6B6B"/>
                            <stop offset="100%" stop-color="#D32F2F"/>
                        </radialGradient>
                        <radialGradient id="gradElectron">
                            <stop offset="0%" stop-color="#4D96FF"/>
                            <stop offset="100%" stop-color="#1976D2"/>
                        </radialGradient>
                    </defs>
                    
                    <!-- Núcleo -->
                    <circle cx="200" cy="150" r="30" fill="url(#gradNucleo)" id="nucleo">
                        <animate attributeName="r" values="30;32;30" dur="2s" repeatCount="indefinite"/>
                    </circle>
                    <text x="200" y="155" fill="white" text-anchor="middle" font-size="10">Núcleo</text>
                    
                    <!-- Electrones (se generan dinámicamente) -->
                    <g id="electronesGrupo"></g>
                    
                    <!-- Órbitas (se generan dinámicamente) -->
                    <g id="orbitasGrupo"></g>
                </svg>
            </div>
            
            <!-- DATOS EN TIEMPO REAL -->
            <div class="datos-simulacion">
                <div class="dato-card">
                    <div class="dato-label">Elemento:</div>
                    <div class="dato-valor" id="datoElemento">Carbono (C)</div>
                </div>
                <div class="dato-card">
                    <div class="dato-label">Modelo:</div>
                    <div class="dato-valor" id="datoModelo">Rutherford</div>
                </div>
                <div class="dato-card">
                    <div class="dato-label">Electrones:</div>
                    <div class="dato-valor" id="datoElectrones">6</div>
                </div>
                <div class="dato-card">
                    <div class="dato-label">Configuración:</div>
                    <div class="dato-valor" id="datoConfig">1s² 2s² 2p²</div>
                </div>
            </div>
        </div>
    </section>

    <!-- CALCULADORAS INTERACTIVAS -->
    <section class="seccion-compacta calculadoras">
        <h2 class="titulo-seccion">
            <span class="icon">🧮</span>
            HERRAMIENTAS DE CÁLCULO
        </h2>
        
        <div class="grid-calculadoras">
            <!-- CALCULADORA 1: ISÓTOPOS -->
            <div class="calculadora-card">
                <h3>🔢 CALCULADORA DE ISÓTOPOS</h3>
                
                <div class="calc-inputs">
                    <div class="input-group">
                        <label>Elemento:</label>
                        <select id="calcElemento" class="input-control">
                            <option value="C">Carbono (C)</option>
                            <option value="O">Oxígeno (O)</option>
                            <option value="U">Uranio (U)</option>
                        </select>
                    </div>
                    
                    <div class="input-group">
                        <label>Número másico (A):</label>
                        <input type="number" id="calcA" value="12" min="1" max="300" class="input-control">
                    </div>
                    
                    <div class="input-group">
                        <label>Abundancia (%):</label>
                        <input type="number" id="calcAbun" value="98.93" min="0" max="100" step="0.01" class="input-control">
                    </div>
                    
                    <button class="btn-calcular" onclick="calcularIsotopo()">
                        CALCULAR COMPOSICIÓN
                    </button>
                </div>
                
                <div class="calc-resultados" id="resultadoIsotopo">
                    <!-- Resultados aparecen aquí -->
                </div>
            </div>
            
            <!-- CALCULADORA 2: MOL Y AVOGADRO -->
            <div class="calculadora-card">
                <h3>⚖️ CALCULADORA DE MOL</h3>
                
                <div class="calc-inputs">
                    <div class="input-group">
                        <label>Sustancia:</label>
                        <input type="text" id="calcSustancia" value="H₂O" class="input-control">
                    </div>
                    
                    <div class="input-group">
                        <label>Cantidad:</label>
                        <div class="input-dual">
                            <input type="number" id="calcCantidad" value="1" step="0.1" class="input-control">
                            <select id="calcUnidad" class="input-control">
                                <option value="mol">mol</option>
                                <option value="g">gramos</option>
                                <option value="particulas">partículas</option>
                            </select>
                        </div>
                    </div>
                    
                    <button class="btn-calcular" onclick="calcularMol()">
                        CALCULAR CON Nₐ
                    </button>
                </div>
                
                <div class="calc-resultados" id="resultadoMol">
                    <!-- Resultados aparecen aquí -->
                </div>
            </div>
        </div>
        
        <!-- FÓRMULAS CLAVE -->
        <div class="formulas-clave">
            <h4>📐 FÓRMULAS FUNDAMENTALES</h4>
            <div class="formula-grid">
                <div class="formula-item">
                    <div class="formula">\\[ A = Z + N \\]</div>
                    <p>Número másico = protones + neutrones</p>
                </div>
                <div class="formula-item">
                    <div class="formula">\\[ N_A = 6.022 \\times 10^{23} \\]</div>
                    <p>Constante de Avogadro (mol⁻¹)</p>
                </div>
                <div class="formula-item">
                    <div class="formula">\\[ E_n = -\\frac{13.6}{n^2} \\text{ eV} \\]</div>
                    <p>Energía electrón en átomo de H (Bohr)</p>
                </div>
            </div>
        </div>
    </section>

