        },
        Mg: {
            nombre: "Magnesio", simbolo: "Mg", Z: 12,
            configuracion: "[Ne] 3s²", valencia: 2, grupo: 2, periodo: 3,
            bloque: "s", octeto: false
        },
        Al: {
            nombre: "Aluminio", simbolo: "Al", Z: 13,
            configuracion: "[Ne] 3s² 3p¹", valencia: 3, grupo: 13, periodo: 3,
            bloque: "p", octeto: false
        },
        Si: {
            nombre: "Silicio", simbolo: "Si", Z: 14,
            configuracion: "[Ne] 3s² 3p²", valencia: 4, grupo: 14, periodo: 3,
            bloque: "p", octeto: true
        },
        P: {
            nombre: "Fósforo", simbolo: "P", Z: 15,
            configuracion: "[Ne] 3s² 3p³", valencia: 5, grupo: 15, periodo: 3,
            bloque: "p", octeto: false, excepcion: "10 e⁻ en PCl₅"
        },
        S: {
            nombre: "Azufre", simbolo: "S", Z: 16,
            configuracion: "[Ne] 3s² 3p⁴", valencia: 6, grupo: 16, periodo: 3,
            bloque: "p", octeto: false, excepcion: "12 e⁻ en SF₆"
        },
        Cl: {
            nombre: "Cloro", simbolo: "Cl", Z: 17,
            configuracion: "[Ne] 3s² 3p⁵", valencia: 7, grupo: 17, periodo: 3,
            bloque: "p", octeto: false
        },
        Ar: {
            nombre: "Argón", simbolo: "Ar", Z: 18,
            configuracion: "[Ne] 3s² 3p⁶", valencia: 8, grupo: 18, periodo: 3,
            bloque: "p", octeto: true
        },
        Fe: {
            nombre: "Hierro", simbolo: "Fe", Z: 26,
            configuracion: "[Ar] 4s² 3d⁶", valencia: 8, grupo: 8, periodo: 4,
            bloque: "d", octeto: false, excepcion: "Variable (2, 3, etc.)"
        },
        Cu: {
            nombre: "Cobre", simbolo: "Cu", Z: 29,
            configuracion: "[Ar] 4s¹ 3d¹⁰", valencia: 11, grupo: 11, periodo: 4,
            bloque: "d", octeto: false, excepcion: "1 e⁻ de valencia (4s¹)"
        },
        Zn: {
            nombre: "Zinc", simbolo: "Zn", Z: 30,
            configuracion: "[Ar] 4s² 3d¹⁰", valencia: 2, grupo: 12, periodo: 4,
            bloque: "d", octeto: true
        }
    };

    // ===========================================
    // SIMULADOR DE VALENCIA
    // ===========================================
    let simulacionesRealizadas = 0;
    let octetosCompletos = 0;
    let excepcionesEncontradas = 0;

    function simularValencia() {
        const simbolo = document.getElementById(\'elementoSelect\').value;
        const tipoEnlace = document.getElementById(\'enlaceSelect\').value;
        const mostrarOcteto = document.getElementById(\'mostrarOcteto\').checked;

        const elemento = elementos[simbolo];
        if (!elemento) {
            alert("❌ Elemento no encontrado en la base de datos.");
            return;
        }

        // Actualizar datos
        document.getElementById(\'dataElemento\').textContent = elemento.nombre;
        document.getElementById(\'dataSimbolo\').textContent = elemento.simbolo;
        document.getElementById(\'dataConfiguracion\').textContent = elemento.configuracion;
        document.getElementById(\'dataValencia\').textContent = elemento.valencia;
        document.getElementById(\'dataGrupoPeriodo\').textContent = `Grupo ${elemento.grupo}, Período ${elemento.periodo}`;
        document.getElementById(\'dataTipoEnlace\').textContent =
            tipoEnlace === "ionico" ? "Iónico" :
            tipoEnlace === "covalente" ? "Covalente" :
            tipoEnlace === "metalico" ? "Metálico" : "Expansión de Octeto";
        document.getElementById(\'dataOcteto\').textContent =
            elemento.octeto ? "Sí" : elemento.excepcion ? `No (${elemento.excepcion})` : "No";

        // Actualizar estadísticas
        simulacionesRealizadas++;
        document.getElementById(\'statSimulaciones\').textContent = simulacionesRealizadas;
        if (elemento.octeto) octetosCompletos++;
        document.getElementById(\'statOctetos\').textContent = octetosCompletos;
        if (elemento.excepcion) excepcionesEncontradas++;
        document.getElementById(\'statExcepciones\').textContent = excepcionesEncontradas;

        // Dibujar átomo
        dibujarAtomo(elemento, tipoEnlace, mostrarOcteto);

        // Feedback
        let infoText = `✅ Simulación completada: <strong>${elemento.nombre}</strong> (${elemento.simbolo}) con <strong>${elemento.valencia} electrones de valencia</strong>.`;
        if (elemento.excepcion) {
            infoText += `<br>⚠️ <strong>Excepción:</strong> ${elemento.excepcion}.`;
        }
        document.getElementById(\'simulacionInfo\').innerHTML = infoText;
    }

    function dibujarAtomo(elemento, tipoEnlace, mostrarOcteto) {
        const svg = document.getElementById(\'atomSVG\');
        svg.innerHTML = \'\';

        // Colores por bloque
        const coloresBloque = {
            s: \'#FF5252\',   // Rojo
            p: \'#4CAF50\',   // Verde
            d: \'#FF9800\',   // Naranja
            f: \'#7B1FA2\'    // Morado
        };
        const color = coloresBloque[elemento.bloque] || \'#E0E0E0\';

        // Dibujar núcleo
        const nucleo = document.createElementNS(\'http://www.w3.org/2000/svg\', \'circle\');
        nucleo.setAttribute(\'cx\', \'100\');
        nucleo.setAttribute(\'cy\', \'100\');
        nucleo.setAttribute(\'r\', \'20\');
        nucleo.setAttribute(\'fill\', color);
        svg.appendChild(nucleo);

        const textoSimbolo = document.createElementNS(\'http://www.w3.org/2000/svg\', \'text\');
        textoSimbolo.setAttribute(\'x\', \'100\');
        textoSimbolo.setAttribute(\'y\', \'105\');
        textoSimbolo.setAttribute(\'fill\', \'white\');
        textoSimbolo.setAttribute(\'text-anchor\', \'middle\');
        textoSimbolo.setAttribute(\'font-size\', \'16\');
        textoSimbolo.setAttribute(\'font-weight\', \'bold\');
        textoSimbolo.textContent = elemento.simbolo;
        svg.appendChild(textoSimbolo);

        // Dibujar electrones de valencia según tipo de enlace
        if (tipoEnlace === "ionico") {
            // Simular pérdida/ganancia de electrones
            const electrones = Math.min(elemento.valencia, 4); // Máximo 4 para visualización
            const anguloIncremento = (2 * Math.PI) / electrones;

            for (let i = 0; i < electrones; i++) {
                const angulo = i * anguloIncremento;
                const x = 100 + 40 * Math.cos(angulo);
                const y = 100 + 40 * Math.sin(angulo);

                const electron = document.createElementNS(\'http://www.w3.org/2000/svg\', \'circle\');
                electron.setAttribute(\'cx\', x);
                electron.setAttribute(\'cy\', y);
                electron.setAttribute(\'r\', \'8\');
                electron.setAttribute(\'fill\', \'#FFEB3B\'); // Amarillo para electrones
                electron.setAttribute(\'stroke\', color);
                electron.setAttribute(\'stroke-width\', \'2\');

                // Animación de pérdida/ganancia
                if (elemento.grupo <= 3 || elemento.bloque === \'s\') {
                    // Metales: pierden electrones
                    electron.setAttribute(\'opacity\', \'1\');
                    const animate = document.createElementNS(\'http://www.w3.org/2000/svg\', \'animate\');
                    animate.setAttribute(\'attributeName\', \'opacity\');
                    animate.setAttribute(\'values\', \'1;0\');
                    animate.setAttribute(\'begin\', `${1 + i * 0.5}s`);
                    animate.setAttribute(\'dur\', \'1s\');
                    animate.setAttribute(\'fill\', \'freeze\');
                    electron.appendChild(animate);
                } else {
                    // No metales: ganan electrones
                    electron.setAttribute(\'opacity\', \'0\');
                    const animate = document.createElementNS(\'http://www.w3.org/2000/svg\', \'animate\');
                    animate.setAttribute(\'attributeName\', \'opacity\');
                    animate.setAttribute(\'values\', \'0;1\');
                    animate.setAttribute(\'begin\', `${1 + i * 0.5}s`);
                    animate.setAttribute(\'dur\', \'1s\');
                    animate.setAttribute(\'fill\', \'freeze\');
                    electron.appendChild(animate);
                }
                svg.appendChild(electron);
            }

            // Dibujar otro átomo para enlace iónico (ej: Cl)
            if (elemento.grupo <= 3) {
                const otroAtomo = elementos.Cl;
                const nucleoOtro = document.createElementNS(\'http://www.w3.org/2000/svg\', \'circle\');
                nucleoOtro.setAttribute(\'cx\', \'160\');
                nucleoOtro.setAttribute(\'cy\', \'100\');
                nucleoOtro.setAttribute(\'r\', \'20\');
                nucleoOtro.setAttribute(\'fill\', coloresBloque[otroAtomo.bloque]);
                svg.appendChild(nucleoOtro);

                const textoOtro = document.createElementNS(\'http://www.w3.org/2000/svg\', \'text\');
                textoOtro.setAttribute(\'x\', \'160\');
                textoOtro.setAttribute(\'y\', \'105\');
                textoOtro.setAttribute(\'fill\', \'white\');
                textoOtro.setAttribute(\'text-anchor\', \'middle\');
                textoOtro.setAttribute(\'font-size\', \'16\');
                textoOtro.textContent = otroAtomo.simbolo;
                svg.appendChild(textoOtro);

                // Flecha de transferencia
                const flecha = document.createElementNS(\'http://www.w3.org/2000/svg\', \'path\');
                flecha.setAttribute(\'d\', \'M120,100 L140,100\');
                flecha.setAttribute(\'stroke\', \'#E0E0E0\');
                flecha.setAttribute(\'stroke-width\', \'2\');
                flecha.setAttribute(\'marker-end\', \'url(#arrowhead)\');
                svg.appendChild(flecha);

                // Electrones transferidos
                for (let i = 0; i < Math.min(elemento.valencia, 2); i++) {
                    const electron = document.createElementNS(\'http://www.w3.org/2000/svg\', \'circle\');
                    electron.setAttribute(\'cx\', 130 + i * 10);
                    electron.setAttribute(\'cy\', 90 - i * 10);
                    electron.setAttribute(\'r\', \'5\');
                    electron.setAttribute(\'fill\', \'#FFEB3B\');
                    svg.appendChild(electron);
                }
            }

        } else if (tipoEnlace === "covalente") {
            // Simular compartición de electrones
            const electrones = elemento.valencia;
            const anguloIncremento = (2 * Math.PI) / electrones;

            for (let i = 0; i < electrones; i++) {
                const angulo = i * anguloIncremento;
                const x = 100 + 40 * Math.cos(angulo);
                const y = 100 + 40 * Math.sin(angulo);

                const electron = document.createElementNS(\'http://www.w3.org/2000/svg\', \'circle\');
                electron.setAttribute(\'cx\', x);
                electron.setAttribute(\'cy\', y);
                electron.setAttribute(\'r\', \'8\');
                electron.setAttribute(\'fill\', \'#FFEB3B\');
                electron.setAttribute(\'stroke\', color);
                electron.setAttribute(\'stroke-width\', \'2\');
                svg.appendChild(electron);

                // Pares de electrones compartidos
                if (i % 2 === 1) {
                    const otroAtomoAngulo = angulo + Math.PI;
                    const otroX = 100 + 30 * Math.cos(otroAtomoAngulo);
                    const otroY = 100 + 30 * Math.sin(otroAtomoAngulo);

                    const otroElectron = document.createElementNS(\'http://www.w3.org/2000/svg\', \'circle\');
                    otroElectron.setAttribute(\'cx\', otroX);
                    otroElectron.setAttribute(\'cy\', otroY);
                    otroElectron.setAttribute(\'r\', \'8\');
                    otroElectron.setAttribute(\'fill\', \'#FFEB3B\');
                    otroElectron.setAttribute(\'stroke\', color);
                    otroElectron.setAttribute(\'stroke-width\', \'2\');
                    svg.appendChild(otroElectron);

                    // Línea de enlace
                    const enlace = document.createElementNS(\'http://www.w3.org/2000/svg\', \'line\');
                    enlace.setAttribute(\'x1\', x);
                    enlace.setAttribute(\'y1\', y);
                    enlace.setAttribute(\'x2\', otroX);
                    enlace.setAttribute(\'y2\', otroY);
                    enlace.setAttribute(\'stroke\', \'#E0E0E0\');
                    enlace.setAttribute(\'stroke-width\', \'2\');
                    enlace.setAttribute(\'stroke-dasharray\', \'5,2\');
                    svg.appendChild(enlace);
                }
            }

        } else if (tipoEnlace === "metalico") {
            // Simular mar de electrones
            const electrones = 10; // Número arbitrario para visualización
            for (let i = 0; i < electrones; i++) {
                const angulo = Math.random() * 2 * Math.PI;
                const distancia = 30 + Math.random() * 40;
                const x = 100 + distancia * Math.cos(angulo);
                const y = 100 + distancia * Math.sin(angulo);

                const electron = document.createElementNS(\'http://www.w3.org/2000/svg\', \'circle\');
                electron.setAttribute(\'cx\', x);
                electron.setAttribute(\'cy\', y);
                electron.setAttribute(\'r\', \'5\');
                electron.setAttribute(\'fill\', \'#FFEB3B\');

                // Animación de movimiento aleatorio
                const animateX = document.createElementNS(\'http://www.w3.org/2000/svg\', \'animate\');
                animateX.setAttribute(\'attributeName\', \'cx\');
                animateX.setAttribute(\'values\', `${x};${x + (Math.random() - 0.5) * 20};${x}`);
                animateX.setAttribute(\'dur\', \'3s\');
                animateX.setAttribute(\'repeatCount\', \'indefinite\');
                electron.appendChild(animateX);

                const animateY = document.createElementNS(\'http://www.w3.org/2000/svg\', \'animate\');
                animateY.setAttribute(\'attributeName\', \'cy\');
                animateY.setAttribute(\'values\', `${y};${y + (Math.random() - 0.5) * 20};${y}`);
                animateY.setAttribute(\'dur\', \'3s\');
                animateY.setAttribute(\'repeatCount\', \'indefinite\');
                electron.appendChild(animateY);

                svg.appendChild(electron);
            }

            // Dibujar otros átomos metálicos
            for (let i = 0; i < 4; i++) {
                const angulo = (i * 2 * Math.PI) / 4;
                const distancia = 60;
                const x = 100 + distancia * Math.cos(angulo);
                const y = 100 + distancia * Math.sin(angulo);

                const otroNucleo = document.createElementNS(\'http://www.w3.org/2000/svg\', \'circle\');
                otroNucleo.setAttribute(\'cx\', x);
                otroNucleo.setAttribute(\'cy\', y);
                otroNucleo.setAttribute(\'r\', \'15\');
                otroNucleo.setAttribute(\'fill\', color);
                svg.appendChild(otroNucleo);

                const textoOtro = document.createElementNS(\'http://www.w3.org/2000/svg\', \'text\');
                textoOtro.setAttribute(\'x\', x);
                textoOtro.setAttribute(\'y\', y + 5);
                textoOtro.setAttribute(\'fill\', \'white\');
                textoOtro.setAttribute(\'text-anchor\', \'middle\');
                textoOtro.setAttribute(\'font-size\', \'12\');
                textoOtro.textContent = elemento.simbolo;
                svg.appendChild(textoOtro);
            }

        } else if (tipoEnlace === "octeto") {
            // Simular expansión de octeto (ej: PCl₅)
            const electrones = elemento.valencia + 2; // Para visualizar expansión
            const anguloIncremento = (2 * Math.PI) / electrones;

            for (let i = 0; i < electrones; i++) {
                const angulo = i * anguloIncremento;
                const x = 100 + 50 * Math.cos(angulo);
                const y = 100 + 50 * Math.sin(angulo);

                const electron = document.createElementNS(\'http://www.w3.org/2000/svg\', \'circle\');
                electron.setAttribute(\'cx\', x);
                electron.setAttribute(\'cy\', y);
                electron.setAttribute(\'r\', \'8\');
                electron.setAttribute(\'fill\', \'#FFEB3B\');
                electron.setAttribute(\'stroke\', color);
                electron.setAttribute(\'stroke-width\', \'2\');
                svg.appendChild(electron);

                // Dibujar átomos de Cl alrededor
                if (i % 2 === 0 && i < 6) { // Máximo 6 para visualización (ej: SF₆)
                    const clX = 100 + 70 * Math.cos(angulo);
                    const clY = 100 + 70 * Math.sin(angulo);

                    const nucleoCl = document.createElementNS(\'http://www.w3.org/2000/svg\', \'circle\');
                    nucleoCl.setAttribute(\'cx\', clX);
                    nucleoCl.setAttribute(\'cy\', clY);
                    nucleoCl.setAttribute(\'r\', \'15\');
                    nucleoCl.setAttribute(\'fill\', \'#4CAF50\');
                    svg.appendChild(nucleoCl);

                    const textoCl = document.createElementNS(\'http://www.w3.org/2000/svg\', \'text\');
                    textoCl.setAttribute(\'x\', clX);
                    textoCl.setAttribute(\'y\', clY + 5);
                    textoCl.setAttribute(\'fill\', \'white\');
                    textoCl.setAttribute(\'text-anchor\', \'middle\');
                    textoCl.setAttribute(\'font-size\', \'12\');
                    textoCl.textContent = \'Cl\';
                    svg.appendChild(textoCl);

                    // Línea de enlace
                    const enlace = document.createElementNS(\'http://www.w3.org/2000/svg\', \'line\');
                    enlace.setAttribute(\'x1\', x);
                    enlace.setAttribute(\'y1\', y);
                    enlace.setAttribute(\'x2\', clX - 15 * Math.cos(angulo));
                    enlace.setAttribute(\'y2\', clY - 15 * Math.sin(angulo));
                    enlace.setAttribute(\'stroke\', \'#E0E0E0\');
                    enlace.setAttribute(\'stroke-width\', \'2\');
                    svg.appendChild(enlace);
                }
            }

            // Resaltar expansión de octeto
            if (mostrarOcteto && elemento.excepcion) {
                const textoExcepcion = document.createElementNS(\'http://www.w3.org/2000/svg\', \'text\');
                textoExcepcion.setAttribute(\'x\', \'100\');
                textoExcepcion.setAttribute(\'y\', \'180\');
                textoExcepcion.setAttribute(\'fill\', \'#FFFF00\');
                textoExcepcion.setAttribute(\'text-anchor\', \'middle\');
                textoExcepcion.setAttribute(\'font-size\', \'14\');
                textoExcepcion.setAttribute(\'font-weight\', \'bold\');
                textoExcepcion.textContent = `⚠️ EXCEPCIÓN: ${elemento.excepcion}`;
                svg.appendChild(textoExcepcion);
            }
        }

        // Resaltar octeto si está completo
        if (mostrarOcteto && elemento.octeto) {
            const octetoCircle = document.createElementNS(\'http://www.w3.org/2000/svg\', \'circle\');
            octetoCircle.setAttribute(\'cx\', \'100\');
            octetoCircle.setAttribute(\'cy\', \'100\');
            octetoCircle.setAttribute(\'r\', \'50\');
            octetoCircle.setAttribute(\'fill\', \'none\');
            octetoCircle.setAttribute(\'stroke\', \'#39FF14\');
            octetoCircle.setAttribute(\'stroke-width\', \'3\');
            octetoCircle.setAttribute(\'stroke-dasharray\', \'10,5\');
            svg.appendChild(octetoCircle);

            const textoOcteto = document.createElementNS(\'http://www.w3.org/2000/svg\', \'text\');
            textoOcteto.setAttribute(\'x\', \'100\');
            textoOcteto.setAttribute(\'y\', \'190\');
            textoOcteto.setAttribute(\'fill\', \'#39FF14\');
            textoOcteto.setAttribute(\'text-anchor\', \'middle\');
            textoOcteto.setAttribute(\'font-size\', \'14\');
            textoOcteto.textContent = \'✅ OCTETO COMPLETO\';
            svg.appendChild(textoOcteto);
        }
    }

    function elementoAleatorio() {
        const simbolos = Object.keys(elementos);
        const simboloAleatorio = simbolos[Math.floor(Math.random() * simbolos.length)];
        document.getElementById(\'elementoSelect\').value = simboloAleatorio;
        document.getElementById(\'simulacionInfo\').textContent =
            `🎲 Elemento aleatorio: <strong>${elementos[simboloAleatorio].nombre}</strong>. Selecciona un enlace y haz clic en "SIMULAR VALENCIA".`;
    }

    // ===========================================
    // QUIZ INTERACTIVO
    // ===========================================
    let quizRespuestas = [];
    let quizCompletado = false;

    document.querySelectorAll(\'.quiz-option\').forEach(option => {
        option.addEventListener(\'click\', function() {
            if (quizCompletado) return;

            const question = this.closest(\'.quiz-question\');
            const correct = question.dataset.correct;
            const selected = this.dataset.value;
            const feedback = question.querySelector(\'.quiz-feedback\');

            // Remover selección previa
            question.querySelectorAll(\'.quiz-option\').forEach(opt => {
                opt.classList.remove(\'selected\', \'correct\', \'incorrect\');
            });

            // Marcar selección actual
            this.classList.add(\'selected\');

            // Verificar respuesta
            if (selected === correct) {
                this.classList.add(\'correct\');
                quizRespuestas.push(true);
            } else {
                this.classList.add(\'incorrect\');
                // Marcar también la correcta
                question.querySelector(`[data-value="${correct}"]`).classList.add(\'correct\');
                quizRespuestas.push(false);
            }

            // Mostrar feedback
            feedback.style.display = \'block\';

            // Verificar si todas las preguntas están respondidas
            const allAnswered = Array.from(document.querySelectorAll(\'.quiz-question\')).every(q =>
                q.querySelector(\'.quiz-option.selected\')
            );
            if (allAnswered && !quizCompletado) {
                quizCompletado = true;
                mostrarResultadosQuiz();
            }
        });
    });

    function mostrarResultadosQuiz() {
        const correctas = quizRespuestas.filter(r => r).length;
        const total = quizRespuestas.length;
        const porcentaje = Math.round((correctas / total) * 100);

        document.getElementById(\'quizScore\').textContent = `${correctas}/${total}`;

        let feedback = "";
        if (porcentaje >= 90) {
            feedback = "🌟 ¡Excelente! Dominas los electrones de valencia y la Regla del Octeto.";
        } else if (porcentaje >= 70) {
            feedback = "👍 Buen trabajo, pero repasa las excepciones y la tabla periódica.";
        } else {
            feedback = "📚 Necesitas estudiar más sobre valencia y reactividad.";
        }
        document.getElementById(\'quizFeedback\').textContent = feedback;
        document.querySelector(\'.quiz-results\').style.display = \'block\';
    }

    function reiniciarQuiz() {
        quizRespuestas = [];
        quizCompletado = false;

        // Limpiar selecciones
        document.querySelectorAll(\'.quiz-option\').forEach(opt => {
            opt.classList.remove(\'selected\', \'correct\', \'incorrect\');
        });

        // Ocultar feedbacks
        document.querySelectorAll(\'.quiz-feedback\').forEach(fb => {
            fb.style.display = \'none\';
        });

        // Ocultar resultados
        document.querySelector(\'.quiz-results\').style.display = \'none\';
    }

    // ===========================================
    // ERRORES COMUNES
    // ===========================================
    function toggleError(header) {
        const content = header.nextElementSibling;
        const toggle = header.querySelector(\'.error-toggle\');

        if (content.style.display === \'block\') {
            content.style.display = \'none\';
            toggle.textContent = \'+\';
        } else {
            content.style.display = \'block\';
            toggle.textContent = \'-\';
        }
    }

    function mostrarSolucion(num) {
        const solucion = document.getElementById(`solucion${num}`);
        solucion.style.display = solucion.style.display === \'block\' ? \'none\' : \'block\';
    }

    // ===========================================
    // PROBLEMAS TIPO EXAMEN
    // ===========================================
    function verificarProblema(num) {
        const solucion = document.getElementById(`solucionP${num}`);
        solucion.style.display = solucion.style.display === \'block\' ? \'none\' : \'block\';
    }

    // ===========================================
    // AUTOEVALUACIÓN
    // ===========================================
    function guardarAutoevaluacion() {
        const slider1 = document.getElementById(\'slider1\').value;
        const slider2 = document.getElementById(\'slider2\').value;
        const slider3 = document.getElementById(\'slider3\').value;
        const promedio = (parseInt(slider1) + parseInt(slider2) + parseInt(slider3)) / 3;

        alert(`💾 Autoevaluación guardada:\\n\\n` +
              `Valencia: ${slider1}/5\\n` +
              `Octeto: ${slider2}/5\\n` +
              `Excepciones: ${slider3}/5\\n\\n` +
              `Promedio: ${promedio.toFixed(1)}/5\\n\\n` +
              `Revisa el plan de estudio según tus resultados.`);
    }

    // ===========================================
