<!-- JAVASCRIPT INTEGRADO -->
<script>
    // ==========================================
    // BASE DE DATOS DE CONFIGURACIONES ELECTRÓNICAS
    // ==========================================
    const configuraciones = {
        "H": { Z: 1, config: "1s1", diagram: { "1s": ["↑"] }, desapareados: 1, regla: "Aufbau" },
        "He": { Z: 2, config: "1s2", diagram: { "1s": ["↑", "↓"] }, desapareados: 0, regla: "Pauli" },
        "Li": { Z: 3, config: "1s2 2s1", diagram: { "1s": ["↑", "↓"], "2s": ["↑"] }, desapareados: 1, regla: "Aufbau" },
        "Be": { Z: 4, config: "1s2 2s2", diagram: { "1s": ["↑", "↓"], "2s": ["↑", "↓"] }, desapareados: 0, regla: "Pauli" },
        "B": { Z: 5, config: "1s2 2s2 2p1", diagram: { "1s": ["↑", "↓"], "2s": ["↑", "↓"], "2p": ["↑"] }, desapareados: 1, regla: "Hund" },
        "C": { Z: 6, config: "1s2 2s2 2p2", diagram: { "1s": ["↑", "↓"], "2s": ["↑", "↓"], "2p": ["↑", "↑"] }, desapareados: 2, regla: "Hund" },
        "N": { Z: 7, config: "1s2 2s2 2p3", diagram: { "1s": ["↑", "↓"], "2s": ["↑", "↓"], "2p": ["↑", "↑", "↑"] }, desapareados: 3, regla: "Hund" },
        "O": { Z: 8, config: "1s2 2s2 2p4", diagram: { "1s": ["↑", "↓"], "2s": ["↑", "↓"], "2p": ["↑↓", "↑", "↑"] }, desapareados: 2, regla: "Hund" },
        "F": { Z: 9, config: "1s2 2s2 2p5", diagram: { "1s": ["↑", "↓"], "2s": ["↑", "↓"], "2p": ["↑↓", "↑↓", "↑"] }, desapareados: 1, regla: "Hund" },
        "Ne": { Z: 10, config: "1s2 2s2 2p6", diagram: { "1s": ["↑", "↓"], "2s": ["↑", "↓"], "2p": ["↑↓", "↑↓", "↑↓"] }, desapareados: 0, regla: "Pauli" },
        "Na": { Z: 11, config: "1s2 2s2 2p6 3s1", diagram: { "1s": ["↑", "↓"], "2s": ["↑", "↓"], "2p": ["↑↓", "↑↓", "↑↓"], "3s": ["↑"] }, desapareados: 1, regla: "Aufbau" },
        "Mg": { Z: 12, config: "1s2 2s2 2p6 3s2", diagram: { "1s": ["↑", "↓"], "2s": ["↑", "↓"], "2p": ["↑↓", "↑↓", "↑↓"], "3s": ["↑", "↓"] }, desapareados: 0, regla: "Pauli" },
        "Al": { Z: 13, config: "1s2 2s2 2p6 3s2 3p1", diagram: { "1s": ["↑", "↓"], "2s": ["↑", "↓"], "2p": ["↑↓", "↑↓", "↑↓"], "3s": ["↑", "↓"], "3p": ["↑"] }, desapareados: 1, regla: "Hund" },
        "Si": { Z: 14, config: "1s2 2s2 2p6 3s2 3p2", diagram: { "1s": ["↑", "↓"], "2s": ["↑", "↓"], "2p": ["↑↓", "↑↓", "↑↓"], "3s": ["↑", "↓"], "3p": ["↑", "↑"] }, desapareados: 2, regla: "Hund" },
        "P": { Z: 15, config: "1s2 2s2 2p6 3s2 3p3", diagram: { "1s": ["↑", "↓"], "2s": ["↑", "↓"], "2p": ["↑↓", "↑↓", "↑↓"], "3s": ["↑", "↓"], "3p": ["↑", "↑", "↑"] }, desapareados: 3, regla: "Hund" },
        "S": { Z: 16, config: "1s2 2s2 2p6 3s2 3p4", diagram: { "1s": ["↑", "↓"], "2s": ["↑", "↓"], "2p": ["↑↓", "↑↓", "↑↓"], "3s": ["↑", "↓"], "3p": ["↑↓", "↑", "↑"] }, desapareados: 2, regla: "Hund" },
        "Cl": { Z: 17, config: "1s2 2s2 2p6 3s2 3p5", diagram: { "1s": ["↑", "↓"], "2s": ["↑", "↓"], "2p": ["↑↓", "↑↓", "↑↓"], "3s": ["↑", "↓"], "3p": ["↑↓", "↑↓", "↑"] }, desapareados: 1, regla: "Hund" },
        "Ar": { Z: 18, config: "1s2 2s2 2p6 3s2 3p6", diagram: { "1s": ["↑", "↓"], "2s": ["↑", "↓"], "2p": ["↑↓", "↑↓", "↑↓"], "3s": ["↑", "↓"], "3p": ["↑↓", "↑↓", "↑↓"] }, desapareados: 0, regla: "Pauli" },
        "Cr": { Z: 24, config: "1s2 2s2 2p6 3s2 3p6 4s1 3d5", diagram: { "1s": ["↑", "↓"], "2s": ["↑", "↓"], "2p": ["↑↓", "↑↓", "↑↓"], "3s": ["↑", "↓"], "3p": ["↑↓", "↑↓", "↑↓"], "4s": ["↑"], "3d": ["↑", "↑", "↑", "↑", "↑"] }, desapareados: 6, regla: "Excepción" },
        "Cu": { Z: 29, config: "1s2 2s2 2p6 3s2 3p6 4s1 3d10", diagram: { "1s": ["↑", "↓"], "2s": ["↑", "↓"], "2p": ["↑↓", "↑↓", "↑↓"], "3s": ["↑", "↓"], "3p": ["↑↓", "↑↓", "↑↓"], "4s": ["↑"], "3d": ["↑↓", "↑↓", "↑↓", "↑↓", "↑↓"] }, desapareados: 1, regla: "Excepción" }
    };

    // ==========================================
    // SIMULADOR DE ORBITALES
    // ==========================================
    function generarDiagrama() {
        const elemento = document.getElementById(\'elementoSelect\').value;
        const configManual = document.getElementById(\'configManual\').value.trim();
        let configData;

        if (configManual) {
            // Procesar configuración manual (simplificado)
            configData = {
                Z: configManual.split(\' \').reduce((sum, orb) => sum + parseInt(orb.replace(/\\D/g, \'\')), 0),
                config: configManual,
                diagram: parseConfigManual(configManual),
                desapareados: 0,
                regla: "Manual"
            };
        } else {
            configData = configuraciones[elemento];
        }

        // Actualizar datos
        document.getElementById(\'tituloElemento\').textContent = `${elemento} (Z=${configData.Z})`;
        document.getElementById(\'dataElemento\').textContent = elemento;
        document.getElementById(\'dataZ\').textContent = configData.Z;
        document.getElementById(\'dataConfiguracion\').textContent = configData.config;
        document.getElementById(\'dataDesapareados\').textContent = configData.desapareados;
        document.getElementById(\'dataRegla\').textContent = configData.regla;

        // Actualizar SVG
        actualizarDiagramaSVG(configData.diagram);
        console.log(`🔬 Diagrama generado para ${elemento}: ${configData.config}`);
    }

    function parseConfigManual(config) {
        // Simplificado: Devuelve un diagrama vacío para configuraciones manuales
        return { "1s": [" ", " "] };
    }

    function actualizarDiagramaSVG(diagram) {
        // Limpiar todos los orbitales
        document.querySelectorAll(\'[id^="e"]\').forEach(el => {
            el.textContent = "[ ]";
        });

        // Llenar según el diagrama
        for (const [orbital, electrones] of Object.entries(diagram)) {
            const orbitalMap = {
                "1s": ["e1s1", "e1s2"],
                "2s": ["e2s1", "e2s2"],
                "2p": ["e2p1", "e2p2", "e2p3", "e2p4", "e2p5", "e2p6"],
                "3s": ["e3s1", "e3s2"],
                "3p": ["e3p1", "e3p2", "e3p3", "e3p4", "e3p5", "e3p6"],
                "4s": ["e4s1", "e4s2"],
                "3d": ["e3d1", "e3d2", "e3d3", "e3d4", "e3d5", "e3d6", "e3d7", "e3d8", "e3d9", "e3d10"]
            };

            if (orbitalMap[orbital]) {
                electrones.forEach((e, i) => {
                    const id = orbitalMap[orbital][i];
                    if (id && document.getElementById(id)) {
                        document.getElementById(id).textContent = `[${e}]`;
                    }
                });
            }
        }
    }

    function elementoAleatorio() {
        const elementos = Object.keys(configuraciones);
        const elem = elementos[Math.floor(Math.random() * elementos.length)];
        document.getElementById(\'elementoSelect\').value = elem;
        document.getElementById(\'configManual\').value = "";
        generarDiagrama();
    }

    function reiniciarSimulador() {
        document.getElementById(\'elementoSelect\').value = "H";
        document.getElementById(\'configManual\').value = "";
        document.getElementById(\'tituloElemento\').textContent = "Selecciona un elemento";
        document.querySelectorAll(\'[id^="e"]\').forEach(el => {
            el.textContent = "[ ]";
        });
        document.getElementById(\'dataElemento\').textContent = "-";
        document.getElementById(\'dataZ\').textContent = "-";
        document.getElementById(\'dataConfiguracion\').textContent = "-";
        document.getElementById(\'dataDesapareados\').textContent = "-";
        document.getElementById(\'dataRegla\').textContent = "-";
    }

    // ==========================================
    // QUIZ INTERACTIVO
    // ==========================================
    let quizRespuestas = [];
    let quizCompletado = false;

    document.querySelectorAll(\'.quiz-option\').forEach(option => {
        option.addEventListener(\'click\', function() {
            if (quizCompletado) return;
            const question = this.closest(\'.quiz-question\');
            const correct = question.dataset.correct;
            const selected = this.dataset.value;
            const feedback = question.querySelector(\'.quiz-feedback\');

            // Remover selección previa
            question.querySelectorAll(\'.quiz-option\').forEach(opt => {
                opt.classList.remove(\'selected\', \'correct\', \'incorrect\');
            });

            // Marcar selección actual
            this.classList.add(\'selected\');
            if (selected === correct) {
                this.classList.add(\'correct\');
                quizRespuestas.push(true);
            } else {
                this.classList.add(\'incorrect\');
                question.querySelector(`[data-value="${correct}"]`).classList.add(\'correct\');
                quizRespuestas.push(false);
            }

            // Mostrar feedback
            feedback.style.display = \'block\';

            // Verificar si todas las preguntas están respondidas
            const allAnswered = Array.from(document.querySelectorAll(\'.quiz-question\')).every(q =>
                q.querySelector(\'.quiz-option.selected\')
            );
            if (allAnswered && !quizCompletado) {
                quizCompletado = true;
                mostrarResultadosQuiz();
            }
        });
    });

    function mostrarResultadosQuiz() {
        const correctas = quizRespuestas.filter(r => r).length;
        document.getElementById(\'quizScore\').textContent = `${correctas}/3`;
        let feedback = "";
        if (correctas >= 2) {
            feedback = "👍 ¡Excelente! Dominas los diagramas de orbitales.";
        } else {
            feedback = "📚 Revisa las reglas de Aufbau, Pauli y Hund.";
        }
        document.getElementById(\'quizFeedback\').textContent = feedback;
        document.querySelector(\'.quiz-results\').style.display = \'block\';
    }

    function reiniciarQuiz() {
        quizRespuestas = [];
        quizCompletado = false;
        document.querySelectorAll(\'.quiz-option\').forEach(opt => {
            opt.classList.remove(\'selected\', \'correct\', \'incorrect\');
        });
        document.querySelectorAll(\'.quiz-feedback\').forEach(fb => {
            fb.style.display = \'none\';
        });
        document.querySelector(\'.quiz-results\').style.display = \'none\';
    }

    // ==========================================
    // ERRORES COMUNES
    // ==========================================
    function toggleError(header) {
        const content = header.nextElementSibling;
        const toggle = header.querySelector(\'.error-toggle\');
        if (content.style.display === \'block\') {
            content.style.display = \'none\';
            toggle.textContent = \'+\';
        } else {
            content.style.display = \'block\';
            toggle.textContent = \'-\';
        }
    }

    // ==========================================
    // PROBLEMAS TIPO EXAMEN
    // ==========================================
    function verificarProblema(num) {
        const solucion = document.getElementById(`solucionP${num}`);
        solucion.style.display = solucion.style.display === \'block\' ? \'none\' : \'block\';
    }

    // ==========================================
    // AUTOEVALUACIÓN
    // ==========================================
    function guardarAutoevaluacion() {
        const slider1 = document.getElementById(\'slider1\').value;
        const slider2 = document.getElementById(\'slider2\').value;
        const promedio = (parseInt(slider1) + parseInt(slider2)) / 2;
        alert(`📊 Autoevaluación guardada:\\n\\n` +
              `Reglas: ${slider1}/5\\n` +
              `Diagramas: ${slider2}/5\\n\\n` +
              `Promedio: ${promedio.toFixed(1)}/5\\n\\n` +
              `¡Sigue practicando con el simulador!`);
    }

    // ==========================================
    // INICIALIZACIÓN
    // ==========================================
    console.log("🚀 Lección Cyberpunk: Diagramas de Orbitales cargada");
    console.log("🎯 Objetivos: Dominar Aufbau, Pauli, Hund y excepciones");
    generarDiagrama(); // Cargar H por defecto
</script>
